const claimConnectionDelivery = `-- name: ClaimConnectionDelivery :one
WITH claimed AS (
    INSERT INTO alert_delivery_attempts (
        organization_id, slug, notification_record_id, alert_policy_id, destination_id,
        destination_type, status, provider_attempt, job_kind, job_queue, job_state,
        queued_at, delivery_lease_until
    )
    SELECT o.id, $1, nr.id, ap.id, ad.id,
        ad.type, 'queued', 1, 'notification_delivery', 'notification_delivery', 'running',
        $2::timestamptz, $3::timestamptz
    FROM organizations o
    JOIN notification_records nr ON nr.organization_id=o.id AND nr.slug=$4
    JOIN alert_destinations ad ON ad.organization_id=o.id AND ad.slug=$5
    JOIN alert_policies ap ON ap.organization_id=o.id AND ap.slug=$6
    JOIN alert_policy_destinations binding ON binding.organization_id=o.id AND binding.destination_id=ad.id AND binding.alert_policy_id=ap.id
    WHERE o.slug=$7 AND ad.type='slack' AND ad.enabled AND ap.enabled
    ON CONFLICT (organization_id, notification_record_id, destination_id) WHERE destination_type='slack'
    DO UPDATE SET
        status='queued', provider_attempt=alert_delivery_attempts.provider_attempt+1,
        delivery_lease_until=EXCLUDED.delivery_lease_until, job_state='running', updated_at=NOW()
    WHERE alert_delivery_attempts.status<>'sent' AND alert_delivery_attempts.job_state<>'cancelled'
        AND (alert_delivery_attempts.delivery_lease_until IS NULL OR alert_delivery_attempts.delivery_lease_until <= $2::timestamptz)
        AND (alert_delivery_attempts.retry_after_at IS NULL OR alert_delivery_attempts.retry_after_at <= $2::timestamptz)
    RETURNING slug, provider_attempt, status, job_state, delivery_lease_until, retry_after_at
)
SELECT claimed.slug, claimed.provider_attempt, claimed.status, claimed.job_state, claimed.delivery_lease_until, claimed.retry_after_at, true AS acquired
FROM claimed
UNION ALL
SELECT attempt.slug, attempt.provider_attempt, attempt.status, attempt.job_state, attempt.delivery_lease_until, attempt.retry_after_at, false AS acquired
FROM alert_delivery_attempts attempt
JOIN organizations o ON o.id=attempt.organization_id
JOIN notification_records nr ON nr.organization_id=o.id AND nr.id=attempt.notification_record_id
JOIN alert_destinations ad ON ad.organization_id=o.id AND ad.id=attempt.destination_id
WHERE o.slug=$7 AND nr.slug=$4 AND ad.slug=$5
    AND attempt.destination_type='slack' AND NOT EXISTS (SELECT 1 FROM claimed)
LIMIT 1
`

type ClaimConnectionDeliveryParams struct {
	AttemptSlug     slug.Slug
	Now             pgtype.Timestamptz
	LeaseUntil      pgtype.Timestamptz
	RecordSlug      slug.Slug
	DestinationSlug slug.Slug
	AlertPolicySlug slug.Slug
	OrgSlug         slug.Slug
}

type ClaimConnectionDeliveryRow struct {
	Slug               slug.Slug
	ProviderAttempt    int32
	Status             string
	JobState           string
	DeliveryLeaseUntil pgtype.Timestamptz
	RetryAfterAt       pgtype.Timestamptz
	Acquired           bool
}

func (q *Queries) ClaimConnectionDelivery(ctx context.Context, arg ClaimConnectionDeliveryParams) (ClaimConnectionDeliveryRow, error) {
	row := q.db.QueryRow(ctx, claimConnectionDelivery,
		arg.AttemptSlug,
		arg.Now,
		arg.LeaseUntil,
		arg.RecordSlug,
		arg.DestinationSlug,
		arg.AlertPolicySlug,
		arg.OrgSlug,
	)
	var i ClaimConnectionDeliveryRow
	err := row.Scan(
		&i.Slug,
		&i.ProviderAttempt,
		&i.Status,
		&i.JobState,
		&i.DeliveryLeaseUntil,
		&i.RetryAfterAt,
		&i.Acquired,
	)
	return i, err
}

