const completePipelineRun = `-- name: CompletePipelineRun :one
UPDATE pipeline_runs pr
SET
    pipeline_version_id = COALESCE(pr.pipeline_version_id, (
        SELECT pv.id FROM pipeline_versions pv WHERE pv.id = $1::bigint
            AND pv.project_id = pr.project_id AND pv.pipeline_slug = pr.pipeline_slug)),
    pipeline_version_spec_hash = COALESCE(pr.pipeline_version_spec_hash, (
        SELECT pv.spec_hash FROM pipeline_versions pv WHERE pv.id = $1::bigint
            AND pv.project_id = pr.project_id AND pv.pipeline_slug = pr.pipeline_slug)),
    deployment_id = COALESCE(pr.deployment_id, $2::bigint),
    deployment_revision = COALESCE(pr.deployment_revision, $3::bigint),
    deployment_resolution_digest = COALESCE(pr.deployment_resolution_digest, $4::text),
    status = $5,
    duration_ms = $6,
    step_count = $7,
    step_slug = $8,
    error_summary = $9,
    failure_kind = $10,
    failure_side = $11,
    started_at = $12::timestamptz,
    ended_at = $13::timestamptz,
    replay_of_run_slug = $14,
    replay_from_step = $15,
    run_mode = $16,
    checkpoint_status = $17,
    incremental_source_step_slug = $18,
    incremental_blocked_reason = $19,
    replay_safety_status = $20,
    replay_blocked_reason = $21,
    backfill_series_slug = $22,
    backfill_chunk_index = $23,
    backfill_chunk_count = $24,
    incremental_diagnostics = $25::jsonb,
    timeline = CASE WHEN pr.timeline ? 'execution_context'
        THEN $26::jsonb || jsonb_build_object('execution_context', pr.timeline->'execution_context')
        ELSE $26::jsonb END
        || CASE WHEN pr.timeline ? 'worker_observed_at' THEN jsonb_build_object(
            'worker_observed_at', GREATEST((pr.timeline->>'worker_observed_at')::timestamptz,
                ($26::jsonb->>'worker_observed_at')::timestamptz)) ELSE '{}'::jsonb END
FROM project_environments pe
JOIN projects p ON pe.project_id = p.id
JOIN organizations o ON p.organization_id = o.id
JOIN environments e ON pe.environment_id = e.id
WHERE
    pr.project_environment_id = pe.id
    AND o.slug = $27
    AND p.slug = $28
    AND e.slug = $29
    AND ((e.deleted_at IS NULL AND pe.deleted_at IS NULL) OR pr.source_type = 'completion')
    AND pr.pipeline_slug = $30
    AND pr.run_slug = $31
    AND pr.status IN ('queued', 'running')
    AND ($1::bigint IS NULL OR pr.pipeline_version_id IS NULL
        OR pr.pipeline_version_id = $1::bigint)
    AND ($1::bigint IS NULL OR EXISTS (
        SELECT 1 FROM pipeline_versions pv WHERE pv.id = $1::bigint
            AND pv.project_id = p.id AND pv.pipeline_slug = pr.pipeline_slug))
    AND (pr.deployment_id IS NULL OR $2::bigint IS NULL
        OR pr.deployment_id = $2::bigint)
    AND (pr.deployment_revision IS NULL OR $3::bigint IS NULL
        OR pr.deployment_revision = $3::bigint)
    AND (pr.deployment_resolution_digest IS NULL OR $4::text IS NULL
        OR pr.deployment_resolution_digest = $4::text)
    -- A revision is an attempt-local compare-and-swap fence, including terminal writes.
    AND (COALESCE(($26::jsonb->>'revision')::bigint, 0)
            = COALESCE((pr.timeline->>'revision')::bigint, 0) + 1
        OR (NOT (pr.timeline ? 'revision') AND NOT ($26::jsonb ? 'revision')))
    AND (NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(NULLIF(pr.timeline->'events', 'null'::jsonb), '[]'::jsonb)) WITH ORDINALITY AS prior(event, position)
        WHERE prior.event IS DISTINCT FROM $26::jsonb->'events'->(prior.position::int - 1)
    ))
    AND (NOT (pr.timeline ? 'revision') OR NOT EXISTS (
        SELECT 1 FROM jsonb_each(pr.timeline) AS identity(key, value)
        WHERE identity.key IN ('compiled_plan_digest', 'deployment_resolution_digest')
            AND identity.value IS DISTINCT FROM $26::jsonb->identity.key
    ))
    AND (NOT (pr.timeline ? 'execution_context')
        OR NOT ($26::jsonb ? 'execution_context')
        OR pr.timeline->'execution_context' = $26::jsonb->'execution_context')
RETURNING
    pr.id, pr.project_environment_id, pr.pipeline_version_id, pr.pipeline_version_spec_hash, pr.api_version, pr.pipeline_slug, pr.run_slug, pr.request_id, pr.source_type, pr.source_summary, pr.source_entrypoint, pr.source_actor_type, pr.source_actor_slug, pr.source_request_id, pr.source_trace_id, pr.source_environment_slug, pr.source_parameter_keys, pr.status, pr.duration_ms, pr.step_count, pr.step_slug, pr.error_summary, pr.failure_kind, pr.failure_side, pr.started_at, pr.ended_at, pr.replay_of_run_slug, pr.replay_from_step, pr.source_event_slug, pr.source_attempt_number, pr.source_root_run_slug, pr.source_retry_of_run_slug, pr.source_schedule_trigger_slug, pr.source_schedule_trigger_revision, pr.source_schedule_cron, pr.source_schedule_timezone, pr.source_schedule_scheduled_fire_at, pr.source_schedule_actual_fire_at, pr.source_schedule_misfire_result, pr.run_mode, pr.checkpoint_status, pr.incremental_source_step_slug, pr.incremental_blocked_reason, pr.replay_safety_status, pr.replay_blocked_reason, pr.backfill_series_slug, pr.backfill_chunk_index, pr.backfill_chunk_count, pr.incremental_diagnostics, pr.timeline, pr.created_at, pr.source_webhook_delivery_id, pr.project_id, pr.deployment_resolution_digest, pr.deployment_id, pr.deployment_revision, pr.worker_job_id,
    (
        SELECT jsonb_build_object(
            'trigger_slug', pt.slug,
            'trigger_revision', pwd.trigger_revision,
            'delivery_id', pwd.delivery_id,
            'payload_digest', pwd.payload_digest,
            'payload_size_bytes', pwd.payload_size_bytes,
            'received_at', pwd.received_at,
            'verification_status', 'verified'
        )
        FROM pipeline_webhook_deliveries pwd
        JOIN pipeline_triggers pt ON pt.id = pwd.pipeline_trigger_id
            AND pt.project_id = pwd.project_id
        WHERE pwd.id = pr.source_webhook_delivery_id
            AND pwd.project_environment_id = pr.project_environment_id
            AND pwd.pipeline_slug = pr.pipeline_slug
    ) AS source_webhook
`

