const createAlertDeliveryAttempt = `-- name: CreateAlertDeliveryAttempt :one
WITH org_row AS (
    SELECT id
    FROM organizations
    WHERE slug = $1
),
record_row AS (
    SELECT nr.id
    FROM notification_records nr
    JOIN org_row o ON o.id = nr.organization_id
    WHERE nr.slug = $2
),
policy_row AS (
    SELECT ap.id
    FROM alert_policies ap
    JOIN org_row o ON o.id = ap.organization_id
    WHERE ap.slug = $3
),
destination_row AS (
    SELECT ad.id
    FROM alert_destinations ad
    JOIN org_row o ON o.id = ad.organization_id
    WHERE ad.slug = $4
),
binding_row AS (
    SELECT 1
    FROM alert_policy_destinations apd
    JOIN policy_row pr ON pr.id = apd.alert_policy_id
    JOIN destination_row dr ON dr.id = apd.destination_id
),
inserted AS (
    INSERT INTO alert_delivery_attempts (
        organization_id,
        slug,
        notification_record_id,
        alert_policy_id,
        destination_id,
        destination_type,
        status,
        provider_attempt,
        job_kind,
        job_queue,
        job_state,
        provider_response_metadata,
        queued_at
    )
    SELECT
        (SELECT id FROM org_row),
        $5::text,
        (SELECT id FROM record_row),
        (SELECT id FROM policy_row),
        (SELECT id FROM destination_row),
        $6::text,
        $7::text,
        $8::int,
        $9::text,
        $10::text,
        $11::text,
        $12::jsonb,
        $13::timestamptz
    WHERE EXISTS (SELECT 1 FROM org_row)
        AND EXISTS (SELECT 1 FROM record_row)
        AND EXISTS (SELECT 1 FROM policy_row)
        AND EXISTS (SELECT 1 FROM destination_row)
        AND EXISTS (SELECT 1 FROM binding_row)
    RETURNING id, slug, notification_record_id, alert_policy_id, destination_id, destination_type, status, provider_attempt, job_kind, job_queue, job_state, provider_response_metadata, error_category, error_message, queued_at, sent_at, failed_at, created_at, updated_at, organization_id, delivery_lease_until, retry_after_at
)
SELECT
    inserted.id, inserted.slug, inserted.notification_record_id, inserted.alert_policy_id, inserted.destination_id, inserted.destination_type, inserted.status, inserted.provider_attempt, inserted.job_kind, inserted.job_queue, inserted.job_state, inserted.provider_response_metadata, inserted.error_category, inserted.error_message, inserted.queued_at, inserted.sent_at, inserted.failed_at, inserted.created_at, inserted.updated_at, inserted.organization_id, inserted.delivery_lease_until, inserted.retry_after_at,
    o.slug AS org_slug,
    nr.slug AS notification_record_slug,
    COALESCE(ap.slug, '')::text AS alert_policy_slug,
    COALESCE(ad.slug, '')::text AS destination_slug,
    COALESCE(ad.name, '')::text AS destination_name
FROM inserted
JOIN notification_records nr ON nr.id = inserted.notification_record_id
JOIN organizations o ON o.id = nr.organization_id
JOIN alert_policies ap ON ap.id = inserted.alert_policy_id
JOIN alert_destinations ad ON ad.id = inserted.destination_id
`

