const createDriftImpactReport = `-- name: CreateDriftImpactReport :one
WITH target AS (
    SELECT
        ps.id AS pipeline_spec_id,
        ds.id AS data_source_id
    FROM organizations o
    LEFT JOIN projects p ON p.organization_id = o.id
        AND p.slug = $8::text
    LEFT JOIN pipeline_specs ps ON ps.project_id = p.id
        AND ps.slug = $9::text
        AND ps.deleted_at IS NULL
    LEFT JOIN data_sources ds ON ds.organization_id = o.id
        AND ds.slug = $10::text
        AND ds.deleted_at IS NULL
    WHERE o.slug = $11
)
INSERT INTO drift_impact_reports (
    pipeline_spec_id,
    data_source_id,
    slug,
    report_type,
    status,
    severity,
    summary,
    changes,
    impacts
)
SELECT
    target.pipeline_spec_id,
    target.data_source_id,
    $1,
    $2,
    $3,
    $4,
    $5,
    $6::jsonb,
    $7::jsonb
FROM target
WHERE (
        target.pipeline_spec_id IS NOT NULL
        AND target.data_source_id IS NULL
    )
    OR (
        target.pipeline_spec_id IS NULL
        AND target.data_source_id IS NOT NULL
    )
RETURNING id, pipeline_spec_id, data_source_id, slug, report_type, status, severity, summary, changes, impacts, created_at, superseded_at
`

