const createOAuthGrant = `-- name: CreateOAuthGrant :one
WITH target AS (
    SELECT
        ds.id,
        ds.organization_id,
        ds.credential_id AS old_credential_id,
        c.kind AS old_credential_kind,
        c.status AS old_credential_status
    FROM data_sources ds
    JOIN organizations o ON o.id = ds.organization_id
    JOIN credentials c ON c.id = ds.credential_id
        AND c.organization_id = ds.organization_id
    WHERE
        o.slug = $1
        AND ds.slug = $2
        AND ds.deleted_at IS NULL
    AND ds.organization_gitlab_connection_id IS NULL
    FOR UPDATE OF ds
),
pending AS (
    SELECT target.old_credential_id AS id
    FROM target
    WHERE
        $3 = 'create_grant'
        AND target.old_credential_kind = 'oauth2_grant'
        AND target.old_credential_status = 'pending'
        AND NOT EXISTS (
            SELECT 1
            FROM credential_oauth_grants grant_record
            WHERE grant_record.credential_id = target.old_credential_id
        )
),
inserted AS (
    INSERT INTO
        credentials (
            organization_id,
            slug,
            kind,
            status
        )
    SELECT
        target.organization_id,
        $4,
        'oauth2_grant',
        $5
    FROM target
    WHERE $3 = 'rotate_grant'
    RETURNING id, organization_id, slug, kind, credential_type, status, encrypted_payload, rotated_at, revoked_at, failure_code, failure_message, created_at, updated_at
),
selected AS (
    SELECT pending.id
    FROM pending
    UNION ALL
    SELECT inserted.id
    FROM inserted
),
activated_pending AS (
    UPDATE credentials c
    SET
        status = 'active',
        failure_code = NULL,
        failure_message = NULL,
        updated_at = NOW()
    FROM pending
    WHERE c.id = pending.id
    RETURNING c.id, c.organization_id, c.slug, c.kind, c.credential_type, c.status, c.encrypted_payload, c.rotated_at, c.revoked_at, c.failure_code, c.failure_message, c.created_at, c.updated_at
),
active_credential AS (
    SELECT inserted.id, inserted.organization_id, inserted.slug, inserted.kind, inserted.credential_type, inserted.status, inserted.encrypted_payload, inserted.rotated_at, inserted.revoked_at, inserted.failure_code, inserted.failure_message, inserted.created_at, inserted.updated_at
    FROM inserted
    UNION ALL
    SELECT activated_pending.id, activated_pending.organization_id, activated_pending.slug, activated_pending.kind, activated_pending.credential_type, activated_pending.status, activated_pending.encrypted_payload, activated_pending.rotated_at, activated_pending.revoked_at, activated_pending.failure_code, activated_pending.failure_message, activated_pending.created_at, activated_pending.updated_at
    FROM activated_pending
),
attached AS (
    UPDATE data_sources ds
    SET
        credential_id = selected.id,
        connection_test_revision = ds.connection_test_revision + 1,
        updated_at = NOW()
    FROM selected, target
    WHERE
        ds.id = target.id
    RETURNING
        ds.id,
        target.old_credential_id,
        selected.id AS new_credential_id
),
retired AS (
    UPDATE credentials c
    SET
        status = 'rotated',
        rotated_at = NOW(),
        encrypted_payload = NULL,
        updated_at = NOW()
    FROM attached
    WHERE
        c.id = attached.old_credential_id
        AND c.id <> attached.new_credential_id
        AND NOT EXISTS (
            SELECT 1
            FROM data_sources ds2
            WHERE
                ds2.credential_id = attached.old_credential_id
                AND ds2.id <> attached.id
        )
    RETURNING c.id
),
tombstoned_old_grants AS (
    UPDATE credential_oauth_grants g
    SET
        encrypted_token_set = decode('', 'hex'),
        updated_at = NOW()
    FROM retired
    WHERE g.credential_id = retired.id
    RETURNING g.credential_id
),
upserted AS (
    INSERT INTO
        credential_oauth_grants (
            credential_id,
            provider,
            encrypted_token_set,
            access_token_expires_at,
            scopes,
            account,
            last_refreshed_at
        )
    SELECT
        selected.id,
        $6,
        $7,
        $8,
        $9::text[],
        $10::jsonb,
        $11
    FROM selected
    JOIN attached ON true
    ON CONFLICT (credential_id)
    DO UPDATE SET
        provider = EXCLUDED.provider,
        encrypted_token_set = EXCLUDED.encrypted_token_set,
        access_token_expires_at = EXCLUDED.access_token_expires_at,
        scopes = EXCLUDED.scopes,
        account = EXCLUDED.account,
        last_refreshed_at = EXCLUDED.last_refreshed_at,
        updated_at = NOW()
    RETURNING id, credential_id, provider, encrypted_token_set, access_token_expires_at, scopes, account, last_refreshed_at, created_at, updated_at
)
SELECT
    active_credential.id, active_credential.organization_id, active_credential.slug, active_credential.kind, active_credential.credential_type, active_credential.status, active_credential.encrypted_payload, active_credential.rotated_at, active_credential.revoked_at, active_credential.failure_code, active_credential.failure_message, active_credential.created_at, active_credential.updated_at,
    upserted.id AS grant_id,
    upserted.provider,
    upserted.encrypted_token_set,
    upserted.access_token_expires_at,
    upserted.scopes,
    upserted.account,
    upserted.last_refreshed_at,
    upserted.created_at AS grant_created_at,
    upserted.updated_at AS grant_updated_at
FROM active_credential
JOIN upserted ON true
`

