const createOAuthInstall = `-- name: CreateOAuthInstall :one
WITH inserted AS (
INSERT INTO
    credential_oauth_installs (
        organization_id,
        data_source_id,
        slug,
        provider,
        state_hash,
        encrypted_pkce_verifier,
        intent,
        expected_credential_id,
        expected_credential_status,
        expected_source_revision,
        actor_type,
        actor_slug,
        requested_scopes,
        expires_at
    )
SELECT
    o.id,
    ds.id,
    $1,
    $2,
    $3,
    $4,
    $5,
    c.id,
    c.status,
    ds.connection_test_revision,
    $6,
    $7,
    $8::text[],
    $9
FROM organizations o
JOIN data_sources ds ON ds.organization_id = o.id
JOIN credentials c ON c.id = ds.credential_id
    AND c.organization_id = ds.organization_id
WHERE
    o.slug = $10
    AND ds.slug = $11
    AND ds.deleted_at IS NULL
    AND ds.organization_gitlab_connection_id IS NULL
RETURNING id, organization_id, data_source_id, slug, provider, state_hash, intent, actor_type, actor_slug, requested_scopes, expires_at, consumed_at, created_at, updated_at, expected_credential_id, expected_credential_status, organization_gitlab_connection_id, expected_source_revision, encrypted_pkce_verifier, notification_connection_id, repository_setup_slug, repository_setup_project_slug
)
SELECT
    inserted.id,
    inserted.organization_id,
    inserted.data_source_id,
    inserted.slug,
    inserted.provider,
    inserted.state_hash,
    inserted.encrypted_pkce_verifier,
    inserted.intent,
    expected_credential.slug AS expected_credential_slug,
    inserted.expected_credential_status,
    inserted.expected_source_revision,
    inserted.actor_type,
    inserted.actor_slug,
    inserted.requested_scopes,
    inserted.expires_at,
    inserted.consumed_at,
    inserted.created_at,
    inserted.updated_at
FROM inserted
JOIN credentials expected_credential
    ON expected_credential.organization_id = inserted.organization_id
    AND expected_credential.id = inserted.expected_credential_id
`

