const createPipelineTrigger = `-- name: CreatePipelineTrigger :one
WITH target AS (
    SELECT
        p.id AS project_id,
        pe.id AS project_environment_id,
        ps.id AS pipeline_id,
        ps.slug AS pipeline_slug,
        pinned.id AS pinned_pipeline_version_id
    FROM organizations o
    JOIN projects p ON p.organization_id = o.id
        AND p.slug = $1
    JOIN environments e ON e.organization_id = o.id
        AND e.slug = $2
        AND e.deleted_at IS NULL
    JOIN project_environments pe ON pe.project_id = p.id
        AND pe.environment_id = e.id
        AND pe.deleted_at IS NULL
    JOIN pipeline_specs ps ON ps.project_id = p.id
        AND ps.slug = $3
        AND ps.deleted_at IS NULL
    LEFT JOIN pipeline_versions pinned ON pinned.project_id = p.id
        AND pinned.pipeline_slug = ps.slug
        AND pinned.spec_hash = $4::text
    WHERE o.slug = $5
),
inserted AS (
    INSERT INTO pipeline_triggers (
        project_id,
        project_environment_id,
        pipeline_id,
        pipeline_slug,
        pinned_pipeline_version_id,
        slug,
        name,
        trigger_type,
        enabled,
        version_policy,
        runtime_input_keys,
        retry_enabled,
        retry_max_attempts,
        retry_backoff_strategy,
        retry_initial_delay_seconds,
        retry_max_delay_seconds,
        retry_jitter,
        retryable_failure_kinds,
        retry_max_elapsed_seconds,
        schedule_cron,
        schedule_timezone,
        schedule_misfire_policy,
        receiver_id,
        webhook_verification_strategy,
        webhook_input_mappings,
        completion_config,
        created_by_actor_type,
        created_by_actor_slug,
        updated_by_actor_type,
        updated_by_actor_slug,
        disabled_at
    )
    SELECT
        target.project_id,
        target.project_environment_id,
        target.pipeline_id,
        target.pipeline_slug,
        CASE
            WHEN $6 = 'pinned' THEN target.pinned_pipeline_version_id
            ELSE NULL
        END,
        $7,
        $8,
        $9,
        $10,
        $6,
        $11::text[],
        $12,
        $13,
        $14,
        $15,
        $16,
        $17,
        $18::text[],
        $19::integer,
        $20::text,
        $21::text,
        $22::text,
        $23::text,
        $24::text,
        $25::jsonb,
        $26::jsonb,
        $27,
        $28::text,
        $29,
        $30::text,
        CASE WHEN $10 THEN NULL ELSE NOW() END
    FROM target
    WHERE $6 <> 'pinned'
        OR target.pinned_pipeline_version_id IS NOT NULL
    RETURNING id, project_id, project_environment_id, pipeline_id, pipeline_slug, pinned_pipeline_version_id, slug, name, trigger_type, enabled, revision, version_policy, runtime_input_keys, retry_enabled, retry_max_attempts, retry_backoff_strategy, retry_initial_delay_seconds, retry_max_delay_seconds, retry_jitter, retryable_failure_kinds, retry_max_elapsed_seconds, schedule_cron, schedule_timezone, schedule_misfire_policy, created_by_actor_type, created_by_actor_slug, updated_by_actor_type, updated_by_actor_slug, disabled_at, created_at, updated_at, receiver_id, webhook_verification_strategy, webhook_input_mappings, completion_config
)
SELECT
    inserted.id, inserted.project_id, inserted.project_environment_id, inserted.pipeline_id, inserted.pipeline_slug, inserted.pinned_pipeline_version_id, inserted.slug, inserted.name, inserted.trigger_type, inserted.enabled, inserted.revision, inserted.version_policy, inserted.runtime_input_keys, inserted.retry_enabled, inserted.retry_max_attempts, inserted.retry_backoff_strategy, inserted.retry_initial_delay_seconds, inserted.retry_max_delay_seconds, inserted.retry_jitter, inserted.retryable_failure_kinds, inserted.retry_max_elapsed_seconds, inserted.schedule_cron, inserted.schedule_timezone, inserted.schedule_misfire_policy, inserted.created_by_actor_type, inserted.created_by_actor_slug, inserted.updated_by_actor_type, inserted.updated_by_actor_slug, inserted.disabled_at, inserted.created_at, inserted.updated_at, inserted.receiver_id, inserted.webhook_verification_strategy, inserted.webhook_input_mappings, inserted.completion_config,
    e.slug AS environment_slug,
    ps.slug AS pipeline_slug,
    pinned.spec_hash AS pinned_version_hash,
    ARRAY(SELECT pws.key_version FROM pipeline_webhook_secret_versions pws WHERE pws.pipeline_trigger_id = inserted.id AND pws.enabled ORDER BY pws.key_version) AS enabled_key_versions
FROM inserted
JOIN project_environments pe ON pe.id = inserted.project_environment_id
JOIN environments e ON e.id = pe.environment_id
JOIN pipeline_specs ps ON ps.id = inserted.pipeline_id
LEFT JOIN pipeline_versions pinned ON pinned.id = inserted.pinned_pipeline_version_id
`

