const createPipelineValidationResult = `-- name: CreatePipelineValidationResult :one
WITH target AS (
    SELECT
        p.id AS project_id,
        pe.id AS project_environment_id,
        ps.id AS pipeline_id,
        ps.current_version_id AS pipeline_version_id,
        ps.spec_hash AS pipeline_spec_hash,
        current_version.spec_hash AS current_version_spec_hash
    FROM organizations o
    JOIN projects p ON p.organization_id = o.id
    JOIN project_environments pe ON pe.project_id = p.id
    JOIN environments e ON e.id = pe.environment_id
        AND e.organization_id = o.id
    JOIN pipeline_specs ps ON ps.project_id = p.id
        AND ps.slug = $1
        AND ps.deleted_at IS NULL
    LEFT JOIN pipeline_versions current_version ON current_version.id = ps.current_version_id
    WHERE o.slug = $2
        AND p.slug = $3
        AND e.slug = $4
        AND e.deleted_at IS NULL
        AND pe.deleted_at IS NULL
),
inserted AS (
    INSERT INTO pipeline_validation_results (
        project_id,
        project_environment_id,
        pipeline_id,
        pipeline_version_id,
        validation_slug,
        pipeline_slug,
        source,
        valid,
        spec_hash,
        diagnostics,
        impact_report_slug,
        impact_pipeline_id
    )
    SELECT
        target.project_id,
        target.project_environment_id,
        target.pipeline_id,
        target.pipeline_version_id,
        $5,
        $1,
        $6,
        $7,
        COALESCE($8::text, target.pipeline_spec_hash, target.current_version_spec_hash),
        $9::jsonb,
        $10::text,
        CASE WHEN $10::text IS NOT NULL THEN target.pipeline_id END
    FROM target
    RETURNING id, project_environment_id, pipeline_id, pipeline_version_id, validation_slug, pipeline_slug, source, valid, spec_hash, diagnostics, impact_report_slug, created_at, updated_at, project_id, impact_pipeline_id
)
SELECT
    inserted.id, inserted.project_environment_id, inserted.pipeline_id, inserted.pipeline_version_id, inserted.validation_slug, inserted.pipeline_slug, inserted.source, inserted.valid, inserted.spec_hash, inserted.diagnostics, inserted.impact_report_slug, inserted.created_at, inserted.updated_at, inserted.project_id, inserted.impact_pipeline_id,
    o.slug AS org_slug,
    p.slug AS project_slug,
    e.slug AS environment_slug
FROM inserted
JOIN project_environments pe ON pe.id = inserted.project_environment_id
JOIN projects p ON p.id = pe.project_id
JOIN organizations o ON o.id = p.organization_id
JOIN environments e ON e.id = pe.environment_id
    AND e.organization_id = o.id
`

