const createProofObservationJob = `-- name: CreateProofObservationJob :one
INSERT INTO proof_observation_jobs (
    organization_id, project_id, project_environment_id, candidate_id, data_source_id, slug,
    request_digest, request, authorization_decision, target_ciphertext, policy_version, worker_identity,
    connector_type, operation, reserved_requests, reserved_bytes, reserved_rows, reserved_cost,
    budget_expires_at, deadline_at, evidence_retain_until, metadata_retain_until
)
SELECT o.id, m.project_id, m.project_environment_id, candidate.id, ds.id, $1,
    $2, $3::jsonb, $4::jsonb, $5,
    $6, $7, ds.type, $8,
    $9, $10, $11, $12,
    $13, LEAST($14::timestamptz, clock_timestamp() + $15::bigint * interval '1 microsecond'), $16, $17
FROM organizations o
JOIN proof_change_candidates candidate ON candidate.organization_id = o.id
JOIN proof_change_candidate_mappings m ON m.organization_id = o.id AND m.id = candidate.mapping_id
JOIN data_sources provider ON provider.organization_id = o.id AND provider.id = m.data_source_id
JOIN data_sources ds ON ds.organization_id = o.id
WHERE o.slug = $18 AND candidate.slug = $19
    AND candidate.closed_at IS NULL AND candidate.head_sha = $20 AND candidate.spec_hash = $21
    AND m.project_id = $22 AND m.project_environment_id = $23
    AND candidate.change_request_id = ($3::jsonb #>> '{candidate,change_request_id}')
    AND m.repository_id = ($3::jsonb #>> '{candidate,repository_id}')
    AND m.target_ref = ($3::jsonb #>> '{candidate,target_ref}')
    AND m.pipeline_path = ($3::jsonb #>> '{candidate,pipeline_path}')
    AND provider.slug = ($3::jsonb #>> '{candidate,provider_connection_slug}')
    AND ds.slug = $24 AND ds.type = $25 AND ds.deleted_at IS NULL AND ds.is_active = true
ON CONFLICT (organization_id, slug) DO NOTHING
RETURNING id, organization_id, project_id, project_environment_id, candidate_id, data_source_id, slug, request_digest, request, authorization_decision, target_ciphertext, policy_version, worker_identity, connector_type, operation, state, reserved_requests, reserved_bytes, reserved_rows, reserved_cost, budget_expires_at, deadline_at, evidence_retain_until, metadata_retain_until, canceled_at, started_at, completed_at, result, snapshot_ciphertext, created_at
`

