const declineOrganizationMemberInvitation = `-- name: DeclineOrganizationMemberInvitation :one
WITH declined AS (
    UPDATE organization_member_invitations omi
    SET
        status = 'declined',
        declined_at = $1,
        updated_at = $1
    WHERE
        omi.organization_id = (
            SELECT id
            FROM organizations
            WHERE
                slug = $2
        )
        AND omi.slug = $3
        AND omi.status = 'pending'
    RETURNING
        id, organization_id, slug, email, role_id, invited_by_user_id, accepted_by_user_id, accepted_member_id, token_hash, status, expires_at, last_sent_at, accepted_at, declined_at, revoked_at, expired_at, created_at, updated_at
)
SELECT
    declined.id, declined.organization_id, declined.slug, declined.email, declined.role_id, declined.invited_by_user_id, declined.accepted_by_user_id, declined.accepted_member_id, declined.token_hash, declined.status, declined.expires_at, declined.last_sent_at, declined.accepted_at, declined.declined_at, declined.revoked_at, declined.expired_at, declined.created_at, declined.updated_at,
    o.slug AS organization_slug,
    r.slug AS role_slug,
    COALESCE(invited_by.slug::text, '') AS invited_by_user_slug,
    COALESCE(accepted_by.slug::text, '') AS accepted_user_slug
FROM
    declined
    JOIN organizations o ON declined.organization_id = o.id
    JOIN roles r ON declined.role_id = r.id
    LEFT JOIN users invited_by ON declined.invited_by_user_id = invited_by.id
    LEFT JOIN users accepted_by ON declined.accepted_by_user_id = accepted_by.id
`

