const deleteExpiredProofReceipts = `-- name: DeleteExpiredProofReceipts :many
WITH expired AS MATERIALIZED (
    SELECT receipt.id FROM proof_receipts receipt
    JOIN organizations organization ON organization.id = receipt.organization_id
    WHERE organization.slug = $1
        AND LEAST(receipt.retain_until, receipt.created_at + interval '168 hours') <= statement_timestamp()
    ORDER BY receipt.created_at, receipt.id
    LIMIT 100
    FOR UPDATE OF receipt
), cleared AS (
    UPDATE proof_receipts receipt SET supersedes_receipt_id = NULL
    FROM organizations organization
    WHERE organization.id = receipt.organization_id AND organization.slug = $1
        AND receipt.supersedes_receipt_id IN (SELECT id FROM expired)
        AND receipt.id NOT IN (SELECT id FROM expired)
    RETURNING receipt.id
)
DELETE FROM proof_receipts receipt USING organizations organization
WHERE organization.id = receipt.organization_id AND organization.slug = $1
    AND receipt.id IN (SELECT id FROM expired)
    AND (SELECT count(*) FROM cleared) >= 0
RETURNING receipt.slug, receipt.receipt_key, receipt.evidence_id
`

type DeleteExpiredProofReceiptsRow struct {
	Slug       slug.Slug
	ReceiptKey string
	EvidenceID int64
}

func (q *Queries) DeleteExpiredProofReceipts(ctx context.Context, orgSlug slug.Slug) ([]DeleteExpiredProofReceiptsRow, error) {
	rows, err := q.db.Query(ctx, deleteExpiredProofReceipts, orgSlug)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DeleteExpiredProofReceiptsRow
	for rows.Next() {
		var i DeleteExpiredProofReceiptsRow
		if err := rows.Scan(&i.Slug, &i.ReceiptKey, &i.EvidenceID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

