const ensureDefaultRole = `-- name: EnsureDefaultRole :one
WITH org_row AS (
    SELECT id
    FROM organizations
    WHERE slug = $1
),
inserted AS (
    INSERT INTO roles (
        organization_id,
        slug,
        name,
        is_default
    )
    SELECT
        org_row.id,
        $2,
        $3::text,
        true
    FROM org_row
    ON CONFLICT (organization_id, slug) WHERE deleted_at IS NULL DO NOTHING
    RETURNING id, organization_id, slug, name, is_default, created_at, updated_at, deleted_at, delete_reason
)
SELECT id, organization_id, slug, name, is_default, created_at, updated_at, deleted_at, delete_reason
FROM inserted
UNION ALL
SELECT r.id, r.organization_id, r.slug, r.name, r.is_default, r.created_at, r.updated_at, r.deleted_at, r.delete_reason
FROM roles r
JOIN org_row o ON r.organization_id = o.id
WHERE r.slug = $2
    AND r.deleted_at IS NULL
LIMIT 1
`

