const findLatestProofChangeCandidate = `-- name: FindLatestProofChangeCandidate :one
SELECT candidate.id, candidate.organization_id, candidate.mapping_id, candidate.slug, candidate.candidate_key, candidate.change_request_id, candidate.source_ref, candidate.head_sha, candidate.source_sha256, candidate.spec_hash, candidate.canonical_spec, candidate.supersedes_candidate_id, candidate.closed_at, candidate.created_at
FROM proof_change_candidates candidate
JOIN organizations organization ON organization.id = candidate.organization_id
WHERE organization.slug = $1
    AND candidate.mapping_id = $2
    AND candidate.change_request_id = $3
ORDER BY candidate.created_at DESC, candidate.id DESC
LIMIT 1
`

