const findOrCreatePermissions = `-- name: FindOrCreatePermissions :many
INSERT INTO
    permissions (resource, action)
SELECT resource, action
FROM UNNEST(
        $1::text [], $2::text []
    ) AS t (resource, action)
ON CONFLICT (resource, action) DO
UPDATE
SET
    resource = EXCLUDED.resource
RETURNING
    id, resource, action
`

type FindOrCreatePermissionsParams struct {
	Resources []string
	Actions   []string
}

func (q *Queries) FindOrCreatePermissions(ctx context.Context, arg FindOrCreatePermissionsParams) ([]Permission, error) {
	rows, err := q.db.Query(ctx, findOrCreatePermissions, arg.Resources, arg.Actions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Permission
	for rows.Next() {
		var i Permission
		if err := rows.Scan(&i.ID, &i.Resource, &i.Action); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

