const findPipelineVersionsBySpecHashPrefix = `-- name: FindPipelineVersionsBySpecHashPrefix :many
SELECT pv.id, pv.project_id, pv.pipeline_slug, pv.git_commit_sha, pv.spec_jsonb, pv.spec_hash, pv.created_at, pv.resolved_contracts, pv.source_path
FROM pipeline_versions pv
JOIN projects p ON pv.project_id = p.id
JOIN organizations o ON p.organization_id = o.id
JOIN pipeline_specs ps ON ps.project_id = pv.project_id
    AND ps.slug = pv.pipeline_slug
    AND ps.deleted_at IS NULL
WHERE o.slug = $1
    AND p.slug = $2
    AND pv.pipeline_slug = $3
    AND left(pv.spec_hash, length($4)) = $4
ORDER BY pv.created_at DESC, pv.id DESC
LIMIT 2
`

type FindPipelineVersionsBySpecHashPrefixParams struct {
	OrgSlug        slug.Slug
	ProjectSlug    slug.Slug
	PipelineSlug   string
	SpecHashPrefix string
}

func (q *Queries) FindPipelineVersionsBySpecHashPrefix(ctx context.Context, arg FindPipelineVersionsBySpecHashPrefixParams) ([]PipelineVersion, error) {
	rows, err := q.db.Query(ctx, findPipelineVersionsBySpecHashPrefix,
		arg.OrgSlug,
		arg.ProjectSlug,
		arg.PipelineSlug,
		arg.SpecHashPrefix,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PipelineVersion
	for rows.Next() {
		var i PipelineVersion
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.PipelineSlug,
			&i.GitCommitSha,
			&i.SpecJsonb,
			&i.SpecHash,
			&i.CreatedAt,
			&i.ResolvedContracts,
			&i.SourcePath,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const findPreviousSuccessfulPipelineRun = `-- name: FindPreviousSuccessfulPipelineRun :one
SELECT pr.run_slug, pr.started_at, pr.ended_at
FROM pipeline_runs pr
JOIN project_environments pe ON pe.id = pr.project_environment_id
JOIN projects p ON p.id = pe.project_id AND p.id = pr.project_id
JOIN organizations o ON o.id = p.organization_id
JOIN environments e ON e.id = pe.environment_id
WHERE o.slug = $1
  AND p.slug = $2
  AND e.slug = $3
  AND pr.pipeline_slug = $4
  AND pr.pipeline_version_id = $5
  AND pr.status = 'succeeded'
  AND pr.ended_at < $6::timestamptz
  AND (pr.replay_of_run_slug IS NULL OR pr.source_attempt_number > 1)
  AND pr.backfill_series_slug IS NULL
ORDER BY pr.ended_at DESC, pr.id DESC
LIMIT 1
`

