const getCheckpoint = `-- name: GetCheckpoint :one
SELECT pc.id, pc.project_environment_id, pc.run_slug, pc.step_slug, pc.pipeline_spec, pc.step_results, pc.incremental_source_windows, pc.created_at, pc.updated_at, pc.compiled_plan, pc.compiled_plan_digest, pc.deployment_plan, pc.deployment_resolution_digest
FROM pipeline_checkpoint pc
JOIN project_environments pe ON pc.project_environment_id = pe.id
JOIN projects p ON pe.project_id = p.id
JOIN organizations o ON p.organization_id = o.id
JOIN environments e ON pe.environment_id = e.id
JOIN pipeline_runs pr ON pr.project_environment_id = pc.project_environment_id
    AND pr.run_slug = pc.run_slug
JOIN pipeline_specs ps ON ps.project_id = pe.project_id
    AND ps.slug = pr.pipeline_slug
    AND ps.deleted_at IS NULL
WHERE o.slug = $1
    AND p.slug = $2
    AND e.slug = $3
    AND pc.run_slug = $4
`

type GetCheckpointParams struct {
	OrgSlug         slug.Slug
	ProjectSlug     slug.Slug
	EnvironmentSlug slug.Slug
	RunSlug         string
}

// Historical reads intentionally do not filter environments.deleted_at.
// Deleting an environment catalog row must not hide persisted replay history.
func (q *Queries) GetCheckpoint(ctx context.Context, arg GetCheckpointParams) (PipelineCheckpoint, error) {
	row := q.db.QueryRow(ctx, getCheckpoint,
		arg.OrgSlug,
		arg.ProjectSlug,
		arg.EnvironmentSlug,
		arg.RunSlug,
	)
	var i PipelineCheckpoint
	err := row.Scan(
		&i.ID,
		&i.ProjectEnvironmentID,
		&i.RunSlug,
		&i.StepSlug,
		&i.PipelineSpec,
		&i.StepResults,
		&i.IncrementalSourceWindows,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CompiledPlan,
		&i.CompiledPlanDigest,
		&i.DeploymentPlan,
		&i.DeploymentResolutionDigest,
	)
	return i, err
}

const getCurrentIncrementalCheckpoint = `-- name: GetCurrentIncrementalCheckpoint :one
SELECT pic.id, pic.project_id, pic.project_environment_id, pic.pipeline_slug, pic.pipeline_version_id, pic.source_step_slug, pic.checkpoint_namespace, pic.checkpoint_kind, pic.data_source_slug, pic.operation_type, pic.operation_ref, pic.operation_inline_hash, pic.operation_identity, pic.observed_lower_bound, pic.observed_upper_bound, pic.display_metadata, pic.commit_status, pic.observed_run_slug, pic.committing_run_slug, pic.blocked_reason, pic.observed_at, pic.committed_at, pic.superseded_at, pic.blocked_at, pic.expired_at, pic.created_at
FROM pipeline_incremental_checkpoints pic
JOIN projects p ON p.id = pic.project_id
JOIN organizations o ON o.id = p.organization_id
JOIN project_environments pe ON pe.id = pic.project_environment_id
    AND pe.project_id = p.id
JOIN environments e ON e.id = pe.environment_id
JOIN pipeline_specs ps ON ps.project_id = pic.project_id
    AND ps.slug = pic.pipeline_slug
    AND ps.deleted_at IS NULL
WHERE o.slug = $1
    AND p.slug = $2
    AND e.slug = $3
    AND e.deleted_at IS NULL
    AND pe.deleted_at IS NULL
    AND pic.pipeline_slug = $4
    AND pic.source_step_slug = $5
    AND pic.checkpoint_namespace = $6
    AND pic.operation_identity = $7
    AND pic.commit_status = 'committed'
    AND pic.superseded_at IS NULL
    AND pic.expired_at IS NULL
ORDER BY pic.committed_at DESC, pic.created_at DESC, pic.id DESC
LIMIT 1
`

