const listAPIKeysByOrganization = `-- name: ListAPIKeysByOrganization :many
SELECT
    ak.id, ak.organization_id, ak.slug, ak.name, ak.description, ak.token_hash, ak.token_prefix, ak.created_by_member_id, ak.role_id, ak.expires_at, ak.revoked_at, ak.last_used_at, ak.created_at, ak.updated_at, ak.can_manage_api_keys,
    r.slug AS role_slug,
    COALESCE(u.slug, '') AS created_by_user_slug
FROM
    api_keys ak
    JOIN organizations o ON ak.organization_id = o.id
    JOIN roles r ON ak.role_id = r.id
    LEFT JOIN organization_members om ON ak.created_by_member_id = om.id
    LEFT JOIN users u ON om.user_id = u.id
WHERE
    o.slug = $1
    AND (
        $2::text = ''
        OR r.slug = $2
    )
    AND (
        $3::text IS NULL
        OR (
            (
                $4 = 'created_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (ak.created_at, ak.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (ak.created_at, ak.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'updated_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (ak.updated_at, ak.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (ak.updated_at, ak.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'name'
                AND (
                    (
                        $5 = 'asc'
                        AND (ak.name, ak.slug) > (
                            $7::text,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (ak.name, ak.slug) < (
                            $7::text,
                            $3::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'asc' THEN ak.created_at
    END ASC,
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'desc' THEN ak.created_at
    END DESC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'asc' THEN ak.updated_at
    END ASC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'desc' THEN ak.updated_at
    END DESC,
    CASE
        WHEN $4 = 'name'
        AND $5 = 'asc' THEN ak.name
    END ASC,
    CASE
        WHEN $4 = 'name'
        AND $5 = 'desc' THEN ak.name
    END DESC,
    CASE
        WHEN $5 = 'asc' THEN ak.slug
    END ASC,
    CASE
        WHEN $5 = 'desc' THEN ak.slug
    END DESC
LIMIT $8
`

