const listDataSourceRefs = `-- name: ListDataSourceRefs :many
SELECT
    dsr.id, dsr.slug, dsr.name, dsr.data_source_type, dsr.required_capabilities, dsr.created_at, dsr.updated_at, dsr.pipeline_spec_id,
    ps.slug AS pipeline_slug
FROM
    data_source_refs dsr
    JOIN pipeline_specs ps ON ps.id = dsr.pipeline_spec_id
    JOIN projects p ON ps.project_id = p.id
    JOIN organizations o ON p.organization_id = o.id
WHERE
    o.slug = $1
    AND p.slug = $2
    AND ps.deleted_at IS NULL
    AND (
        $3::text IS NULL
        OR (
            (
                $4 = 'asc'
                AND (dsr.created_at, ps.slug || '/' || dsr.slug) > (
                    $5::timestamptz,
                    $3::text
                )
            )
            OR (
                $4 = 'desc'
                AND (dsr.created_at, ps.slug || '/' || dsr.slug) < (
                    $5::timestamptz,
                    $3::text
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $4 = 'asc' THEN dsr.created_at
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN dsr.created_at
    END DESC,
    CASE
        WHEN $4 = 'asc' THEN ps.slug || '/' || dsr.slug
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN ps.slug || '/' || dsr.slug
    END DESC
LIMIT $6
`

