const listDataSourcesByOrg = `-- name: ListDataSourcesByOrg :many
SELECT
    ds.id, ds.organization_id, ds.credential_id, ds.name, ds.slug, ds.type, ds.config, ds.is_active, ds.read_only, ds.deleted_at, ds.delete_reason, ds.last_tested_at, ds.test_error, ds.created_at, ds.updated_at, ds.schema_import_status, ds.schema_import_error_code, ds.schema_import_error_message, ds.schema_import_attempt_id, ds.schema_import_started_at, ds.schema_import_finished_at, ds.connection_test_revision, ds.organization_gitlab_connection_id, ds.proof_enabled, ds.proof_checks_enabled,
    jsonb_build_object(
        'slug', c.slug,
        'kind', c.kind,
        'status', c.status,
        'provider', CASE
            WHEN c.kind = 'oauth2_grant' THEN COALESCE(g.provider, ds.type)
            ELSE ''
        END,
        'updated_at', c.updated_at,
        'access_token_expires_at', g.access_token_expires_at,
        'scopes', COALESCE(g.scopes, '{}'::text[]),
        'account', COALESCE(g.account, '{}'::jsonb),
        'last_refreshed_at', g.last_refreshed_at,
        'revoked_at', c.revoked_at,
        'failure_code', c.failure_code,
        'failure_message', c.failure_message
    ) AS credential_metadata
FROM
    data_sources ds
    JOIN organizations o ON ds.organization_id = o.id
    JOIN credentials c
        ON c.organization_id = ds.organization_id
        AND c.id = ds.credential_id
    LEFT JOIN credential_oauth_grants g ON g.credential_id = c.id
WHERE
    o.slug = $1
    AND ds.deleted_at IS NULL
    AND (
        $2::text IS NULL
        OR (
            (
                $3 = 'created_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (ds.created_at, ds.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (ds.created_at, ds.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'updated_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (ds.updated_at, ds.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (ds.updated_at, ds.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'name'
                AND (
                    (
                        $4 = 'asc'
                        AND (ds.name, ds.slug) > (
                            $6::text,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (ds.name, ds.slug) < (
                            $6::text,
                            $2::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'asc' THEN ds.created_at
    END ASC,
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'desc' THEN ds.created_at
    END DESC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'asc' THEN ds.updated_at
    END ASC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'desc' THEN ds.updated_at
    END DESC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'asc' THEN ds.name
    END ASC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'desc' THEN ds.name
    END DESC,
    CASE
        WHEN $4 = 'asc' THEN ds.slug
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN ds.slug
    END DESC
LIMIT $7
`

