const listEnvironmentSecrets = `-- name: ListEnvironmentSecrets :many
SELECT
    es.id, es.environment_id, es.credential_id, es.key, es.description, es.created_at, es.updated_at, es.organization_id,
    e.slug AS environment_slug,
    c.slug AS credential_slug
FROM
    environment_secrets es
    JOIN environments e ON e.id = es.environment_id
    JOIN organizations o ON o.id = e.organization_id
    JOIN credentials c ON c.id = es.credential_id
        AND c.organization_id = e.organization_id
WHERE
    o.slug = $1
    AND e.slug = $2
    AND e.deleted_at IS NULL
    AND (
        $3::text IS NULL
        OR (
            (
                $4 = 'asc'
                AND (es.updated_at, es.key) > (
                    $5::timestamptz,
                    $3::text
                )
            )
            OR (
                $4 = 'desc'
                AND (es.updated_at, es.key) < (
                    $5::timestamptz,
                    $3::text
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $4 = 'asc' THEN es.updated_at
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN es.updated_at
    END DESC,
    CASE
        WHEN $4 = 'asc' THEN es.key
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN es.key
    END DESC
LIMIT $6
`

