const listNotificationRecordsByOrganization = `-- name: ListNotificationRecordsByOrganization :many
SELECT
    nr.id, nr.organization_id, nr.slug, nr.project_id, nr.environment_id, nr.notification_type, nr.severity, nr.lifecycle_state, nr.dedupe_fingerprint, nr.source_event_slug, nr.source_entity_type, nr.source_action, nr.source_refs, nr.safe_metadata, nr.first_seen_at, nr.last_seen_at, nr.occurrence_count, nr.last_occurrence_at, nr.dispatch_summary, nr.acknowledged_at, nr.resolved_at, nr.created_at, nr.updated_at,
    COALESCE((SELECT p.slug FROM projects p WHERE p.id = nr.project_id), '')::text AS project_slug,
    COALESCE((SELECT e.slug FROM environments e WHERE e.id = nr.environment_id), '')::text AS environment_slug
FROM notification_records nr
JOIN organizations o ON o.id = nr.organization_id
WHERE o.slug = $1
    AND (
        $2::text IS NULL
        OR nr.lifecycle_state = $2::text
    )
    AND (
        $2::text IS NOT NULL
        OR $3::boolean
        OR nr.lifecycle_state <> 'resolved'
    )
    AND (
        $4::text IS NULL
        OR nr.notification_type = $4::text
    )
    AND (
        $5::text IS NULL
        OR nr.severity = $5::text
    )
    AND (
        $6::text IS NULL
        OR nr.source_entity_type = $6::text
    )
    AND (
        $7::text IS NULL
        OR nr.source_action = $7::text
    )
    AND (
        $8::text IS NULL
        OR nr.source_refs ->> 'source_ref' = $8::text
        OR (
            nr.source_entity_type = 'pipeline_run'
            AND (
                $6::text IS NULL
                OR $6::text = 'pipeline_run'
            )
            AND nr.source_refs ->> 'pipeline_slug' = $8::text
        )
    )
    AND (
        $9::text IS NULL
        OR (
            (
                $10 = 'asc'
                AND (nr.last_seen_at, nr.slug) > (
                    $11::timestamptz,
                    $9::text
                )
            )
            OR (
                $10 = 'desc'
                AND (nr.last_seen_at, nr.slug) < (
                    $11::timestamptz,
                    $9::text
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $10 = 'asc' THEN nr.last_seen_at
    END ASC,
    CASE
        WHEN $10 = 'desc' THEN nr.last_seen_at
    END DESC,
    CASE
        WHEN $10 = 'asc' THEN nr.slug
    END ASC,
    CASE
        WHEN $10 = 'desc' THEN nr.slug
    END DESC
LIMIT $12
`

