const listODCSRevisions = `-- name: ListODCSRevisions :many
SELECT r.id, r.organization_id, r.project_id, r.contract_id, r.slug, r.digest, r.odcs_version, r.document_version, r.declared_status, r.status, r.schema_objects, r.created_at FROM odcs_contract_revisions r
JOIN odcs_contracts c ON c.id = r.contract_id AND c.organization_id = r.organization_id AND c.project_id = r.project_id
JOIN projects p ON p.id = c.project_id AND p.organization_id = c.organization_id
JOIN organizations o ON o.id = c.organization_id
WHERE o.slug = $1 AND p.slug = $2
AND c.slug = $3
AND ($4::text IS NULL OR
    ($5::text = 'asc' AND (r.created_at, r.slug) > ($6::timestamptz, $4::text)) OR
    ($5::text = 'desc' AND (r.created_at, r.slug) < ($6::timestamptz, $4::text)))
ORDER BY
    CASE WHEN $5::text = 'asc' THEN r.created_at END ASC,
    CASE WHEN $5::text = 'desc' THEN r.created_at END DESC,
    CASE WHEN $5::text = 'asc' THEN r.slug END ASC,
    CASE WHEN $5::text = 'desc' THEN r.slug END DESC
LIMIT $7
`

