const listOrganizationMemberInvitations = `-- name: ListOrganizationMemberInvitations :many
SELECT
    omi.id, omi.organization_id, omi.slug, omi.email, omi.role_id, omi.invited_by_user_id, omi.accepted_by_user_id, omi.accepted_member_id, omi.token_hash, omi.status, omi.expires_at, omi.last_sent_at, omi.accepted_at, omi.declined_at, omi.revoked_at, omi.expired_at, omi.created_at, omi.updated_at,
    o.slug AS organization_slug,
    r.slug AS role_slug,
    COALESCE(invited_by.slug::text, '') AS invited_by_user_slug,
    COALESCE(accepted_by.slug::text, '') AS accepted_user_slug
FROM
    organization_member_invitations omi
    JOIN organizations o ON omi.organization_id = o.id
    JOIN roles r ON omi.role_id = r.id
    LEFT JOIN users invited_by ON omi.invited_by_user_id = invited_by.id
    LEFT JOIN users accepted_by ON omi.accepted_by_user_id = accepted_by.id
WHERE
    o.slug = $1
    AND (
        $2::text IS NULL
        OR omi.status = $2::text
    )
    AND (
        $3::text IS NULL
        OR (
            (
                $4 = 'created_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (omi.created_at, omi.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (omi.created_at, omi.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'updated_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (omi.updated_at, omi.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (omi.updated_at, omi.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'email'
                AND (
                    (
                        $5 = 'asc'
                        AND (omi.email, omi.slug) > (
                            $7::text,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (omi.email, omi.slug) < (
                            $7::text,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'expires_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (omi.expires_at, omi.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (omi.expires_at, omi.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'asc' THEN omi.created_at
    END ASC,
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'desc' THEN omi.created_at
    END DESC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'asc' THEN omi.updated_at
    END ASC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'desc' THEN omi.updated_at
    END DESC,
    CASE
        WHEN $4 = 'email'
        AND $5 = 'asc' THEN omi.email
    END ASC,
    CASE
        WHEN $4 = 'email'
        AND $5 = 'desc' THEN omi.email
    END DESC,
    CASE
        WHEN $4 = 'expires_at'
        AND $5 = 'asc' THEN omi.expires_at
    END ASC,
    CASE
        WHEN $4 = 'expires_at'
        AND $5 = 'desc' THEN omi.expires_at
    END DESC,
    CASE
        WHEN $5 = 'asc' THEN omi.slug
    END ASC,
    CASE
        WHEN $5 = 'desc' THEN omi.slug
    END DESC
LIMIT $8
`

