const listPersonalAccessTokensByUser = `-- name: ListPersonalAccessTokensByUser :many
SELECT
    pat.id, pat.user_id, pat.slug, pat.name, pat.description, pat.token_hash, pat.token_prefix, pat.expires_at, pat.revoked_at, pat.last_used_at, pat.created_at, pat.updated_at, pat.can_manage_personal_access_tokens,
    u.slug AS user_slug
FROM
    personal_access_tokens pat
    JOIN users u ON pat.user_id = u.id
WHERE
    u.slug = $1
    AND (
        $2::text IS NULL
        OR (
            (
                $3 = 'created_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (pat.created_at, pat.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (pat.created_at, pat.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'updated_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (pat.updated_at, pat.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (pat.updated_at, pat.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'name'
                AND (
                    (
                        $4 = 'asc'
                        AND (pat.name, pat.slug) > (
                            $6::text,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (pat.name, pat.slug) < (
                            $6::text,
                            $2::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'asc' THEN pat.created_at
    END ASC,
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'desc' THEN pat.created_at
    END DESC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'asc' THEN pat.updated_at
    END ASC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'desc' THEN pat.updated_at
    END DESC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'asc' THEN pat.name
    END ASC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'desc' THEN pat.name
    END DESC,
    CASE
        WHEN $4 = 'asc' THEN pat.slug
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN pat.slug
    END DESC
LIMIT $7
`

