const listPipelineSpecsByProject = `-- name: ListPipelineSpecsByProject :many
SELECT ps.id, ps.project_id, ps.slug, ps.name, ps.current_version_id, ps.spec_jsonb, ps.spec_hash, ps.sync_status, ps.source_path, ps.source_ref, ps.last_applied_commit, ps.deleted_at, ps.deleted_by, ps.delete_reason, ps.created_at, ps.updated_at, pv.spec_hash AS current_version_spec_hash
FROM pipeline_specs ps
JOIN projects p ON ps.project_id = p.id
JOIN organizations o ON p.organization_id = o.id
LEFT JOIN pipeline_versions pv ON pv.id = ps.current_version_id
WHERE
    o.slug = $1
    AND p.slug = $2
    AND ps.deleted_at IS NULL
    AND (
        $3::text IS NULL
        OR (
            (
                COALESCE(NULLIF($4::text, ''), 'desc') = 'asc'
                AND (ps.created_at, ps.slug) > (
                    $5::timestamptz,
                    $3::text
                )
            )
            OR (
                COALESCE(NULLIF($4::text, ''), 'desc') = 'desc'
                AND (ps.created_at, ps.slug) < (
                    $5::timestamptz,
                    $3::text
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN COALESCE(NULLIF($4::text, ''), 'desc') = 'asc' THEN ps.created_at
    END ASC,
    CASE
        WHEN COALESCE(NULLIF($4::text, ''), 'desc') = 'desc' THEN ps.created_at
    END DESC,
    CASE
        WHEN COALESCE(NULLIF($4::text, ''), 'desc') = 'asc' THEN ps.slug
    END ASC,
    CASE
        WHEN COALESCE(NULLIF($4::text, ''), 'desc') = 'desc' THEN ps.slug
    END DESC
LIMIT CASE
    WHEN $6::bigint > 0 THEN $6::bigint
    ELSE NULL
END
`

