const listPipelineValidationResults = `-- name: ListPipelineValidationResults :many
SELECT
    r.id, r.project_environment_id, r.pipeline_id, r.pipeline_version_id, r.validation_slug, r.pipeline_slug, r.source, r.valid, r.spec_hash, r.diagnostics, r.impact_report_slug, r.created_at, r.updated_at, r.project_id, r.impact_pipeline_id,
    o.slug AS org_slug,
    p.slug AS project_slug,
    e.slug AS environment_slug
FROM pipeline_validation_results r
JOIN project_environments pe ON pe.id = r.project_environment_id
JOIN projects p ON p.id = pe.project_id
JOIN organizations o ON o.id = p.organization_id
JOIN environments e ON e.id = pe.environment_id
    AND e.organization_id = o.id
WHERE o.slug = $1
    AND p.slug = $2
    AND e.slug = $3
    AND (
        $4::text IS NULL
        OR EXISTS (
            SELECT 1
            FROM pipeline_specs ps
            WHERE ps.project_id = p.id
                AND ps.slug = $4::text
                AND ps.deleted_at IS NULL
                AND r.pipeline_id = ps.id
        )
    )
ORDER BY r.created_at DESC, r.validation_slug DESC
LIMIT $5
`

