const listProjectEnvironments = `-- name: ListProjectEnvironments :many
SELECT
    pe.id, pe.project_id, pe.environment_id, pe.is_default, pe.deleted_at, pe.delete_reason, pe.enabled_at, pe.updated_at, pe.organization_id,
    e.slug AS environment_slug,
    e.name AS environment_name,
    e.description AS environment_description,
    e.color AS environment_color,
    e.protected AS environment_protected,
    e.deleted_at AS environment_deleted_at,
    e.created_at AS environment_created_at,
    e.updated_at AS environment_updated_at
FROM
    project_environments pe
    JOIN projects p ON pe.project_id = p.id
    JOIN organizations o ON p.organization_id = o.id
    JOIN environments e ON pe.environment_id = e.id
        AND e.organization_id = o.id
WHERE
    o.slug = $1
    AND p.slug = $2
    AND e.deleted_at IS NULL
    AND pe.deleted_at IS NULL
    AND (
        $3::text IS NULL
        OR (
            (
                $4 = 'created_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (e.created_at, e.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (e.created_at, e.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'updated_at'
                AND (
                    (
                        $5 = 'asc'
                        AND (e.updated_at, e.slug) > (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (e.updated_at, e.slug) < (
                            $6::timestamptz,
                            $3::text
                        )
                    )
                )
            )
            OR (
                $4 = 'name'
                AND (
                    (
                        $5 = 'asc'
                        AND (e.name, e.slug) > (
                            $7::text,
                            $3::text
                        )
                    )
                    OR (
                        $5 = 'desc'
                        AND (e.name, e.slug) < (
                            $7::text,
                            $3::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'asc' THEN e.created_at
    END ASC,
    CASE
        WHEN $4 = 'created_at'
        AND $5 = 'desc' THEN e.created_at
    END DESC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'asc' THEN e.updated_at
    END ASC,
    CASE
        WHEN $4 = 'updated_at'
        AND $5 = 'desc' THEN e.updated_at
    END DESC,
    CASE
        WHEN $4 = 'name'
        AND $5 = 'asc' THEN e.name
    END ASC,
    CASE
        WHEN $4 = 'name'
        AND $5 = 'desc' THEN e.name
    END DESC,
    CASE
        WHEN $5 = 'asc' THEN e.slug
    END ASC,
    CASE
        WHEN $5 = 'desc' THEN e.slug
    END DESC
LIMIT $8
`

