const listRecentAlertDeliveryAttemptsForRecords = `-- name: ListRecentAlertDeliveryAttemptsForRecords :many
WITH ranked AS (
    SELECT
        ada.id, ada.slug, ada.notification_record_id, ada.alert_policy_id, ada.destination_id, ada.destination_type, ada.status, ada.provider_attempt, ada.job_kind, ada.job_queue, ada.job_state, ada.provider_response_metadata, ada.error_category, ada.error_message, ada.queued_at, ada.sent_at, ada.failed_at, ada.created_at, ada.updated_at, ada.organization_id, ada.delivery_lease_until, ada.retry_after_at,
        o.slug AS org_slug,
        nr.slug AS notification_record_slug,
        COALESCE(ap.slug, '')::text AS alert_policy_slug,
        COALESCE(ad.slug, '')::text AS destination_slug,
        COALESCE(ad.name, '')::text AS destination_name,
        row_number() OVER (
            PARTITION BY nr.slug
            ORDER BY ada.created_at DESC, ada.slug DESC
        ) AS attempt_rank
    FROM alert_delivery_attempts ada
    JOIN notification_records nr ON nr.id = ada.notification_record_id
    JOIN organizations o ON o.id = nr.organization_id
    LEFT JOIN alert_policies ap ON ap.id = ada.alert_policy_id
        AND ap.organization_id = nr.organization_id
    LEFT JOIN alert_destinations ad ON ad.id = ada.destination_id
        AND ad.organization_id = nr.organization_id
    WHERE o.slug = $2
        AND nr.slug = ANY($3::text[])
)
SELECT id, slug, notification_record_id, alert_policy_id, destination_id, destination_type, status, provider_attempt, job_kind, job_queue, job_state, provider_response_metadata, error_category, error_message, queued_at, sent_at, failed_at, created_at, updated_at, organization_id, delivery_lease_until, retry_after_at, org_slug, notification_record_slug, alert_policy_slug, destination_slug, destination_name, attempt_rank
FROM ranked
WHERE attempt_rank <= $1::int
ORDER BY notification_record_slug, created_at DESC, slug DESC
`

