const listUserOrganizations = `-- name: ListUserOrganizations :many
SELECT
    om.id, om.organization_id, om.user_id, om.role_id, om.created_at, om.updated_at,
    o.name,
    o.slug,
    o.settings,
    o.created_at AS org_created_at,
    o.updated_at AS org_updated_at,
    r.slug AS role_slug
FROM
    organization_members om
    JOIN organizations o ON om.organization_id = o.id
    JOIN users u ON om.user_id = u.id
    JOIN roles r ON om.role_id = r.id
WHERE
    u.slug = $1
    AND (
        $2::text IS NULL
        OR (
            (
                $3 = 'created_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (o.created_at, o.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (o.created_at, o.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'updated_at'
                AND (
                    (
                        $4 = 'asc'
                        AND (o.updated_at, o.slug) > (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (o.updated_at, o.slug) < (
                            $5::timestamptz,
                            $2::text
                        )
                    )
                )
            )
            OR (
                $3 = 'name'
                AND (
                    (
                        $4 = 'asc'
                        AND (o.name, o.slug) > (
                            $6::text,
                            $2::text
                        )
                    )
                    OR (
                        $4 = 'desc'
                        AND (o.name, o.slug) < (
                            $6::text,
                            $2::text
                        )
                    )
                )
            )
        )
    )
ORDER BY
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'asc' THEN o.created_at
    END ASC,
    CASE
        WHEN $3 = 'created_at'
        AND $4 = 'desc' THEN o.created_at
    END DESC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'asc' THEN o.updated_at
    END ASC,
    CASE
        WHEN $3 = 'updated_at'
        AND $4 = 'desc' THEN o.updated_at
    END DESC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'asc' THEN o.name
    END ASC,
    CASE
        WHEN $3 = 'name'
        AND $4 = 'desc' THEN o.name
    END DESC,
    CASE
        WHEN $4 = 'asc' THEN o.slug
    END ASC,
    CASE
        WHEN $4 = 'desc' THEN o.slug
    END DESC
LIMIT $7
`

