func (q *Queries) LockAccountDeletionOrganizations(ctx context.Context, userID int32) ([]LockAccountDeletionOrganizationsRow, error) {
	rows, err := q.db.Query(ctx, lockAccountDeletionOrganizations, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LockAccountDeletionOrganizationsRow
	for rows.Next() {
		var i LockAccountDeletionOrganizationsRow
		if err := rows.Scan(&i.Slug, &i.RoleSlug); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

