const lockAccountJobs = `-- name: LockAccountJobs :many
SELECT id FROM river_job
WHERE state NOT IN ('cancelled', 'completed', 'discarded')
    AND ((kind IN ('pipeline_git_write_file', 'pipeline_git_delete_file') AND args->>'initiating_user_slug' = $1::text)
        OR ((kind IN ('pipeline_git_publish_proposal', 'pipeline_git_refresh_proposal') AND args->>'member_slug' = $1::text)
        OR (kind = 'pipeline_run_execution' AND args->'actor'->>'Type' = 'user' AND args->'actor'->>'Slug' = $1::text)
        OR (kind = 'email_send' AND args->'user'->>'slug' = $1::text)))
ORDER BY id FOR UPDATE
`

// Account removal crosses memberships but cancels only the subject's own jobs.
func (q *Queries) LockAccountJobs(ctx context.Context, userSlug string) ([]int, error) {
	rows, err := q.db.Query(ctx, lockAccountJobs, userSlug)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int
	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

