const markAPIKeyUsed = `-- name: MarkAPIKeyUsed :execrows
UPDATE api_keys ak
SET
    last_used_at = NOW(),
    updated_at = NOW()
FROM organizations o
WHERE
    ak.organization_id = o.id
    AND o.slug = $1
    AND ak.slug = $2
    AND ak.revoked_at IS NULL
    AND (
        ak.expires_at IS NULL
        OR ak.expires_at > NOW()
    )
`

