const markCredentialRevoked = `-- name: MarkCredentialRevoked :one
WITH target AS (
    SELECT
        c.id AS credential_id,
        c.organization_id
    FROM credentials c
    JOIN organizations o ON o.id = c.organization_id
    JOIN credential_oauth_grants g ON g.credential_id = c.id
    WHERE
        o.slug = $1
        AND c.slug = $2
        AND g.updated_at = $3
        AND c.kind = 'oauth2_grant'
        AND (
            ($4::text = 'organization_gitlab' AND EXISTS (
                SELECT 1 FROM organization_gitlab_connections connection
                WHERE connection.organization_id = c.organization_id AND connection.credential_id = c.id
            )) OR ($4::text = 'notification_connection' AND EXISTS (
                SELECT 1 FROM notification_connections connection
                WHERE connection.organization_id = c.organization_id AND connection.credential_id = c.id
                    AND connection.slug = $5
            )) OR ($4::text = 'data_source' AND EXISTS (
                SELECT 1 FROM data_sources ds
                WHERE ds.organization_id = c.organization_id AND ds.credential_id = c.id
                    AND ds.slug = $6 AND ds.deleted_at IS NULL
                    AND ds.organization_gitlab_connection_id IS NULL
            ))
        )
    FOR UPDATE OF c, g
),
tombstoned AS (
    UPDATE credential_oauth_grants g
    SET
        encrypted_token_set = decode('', 'hex'),
        updated_at = NOW()
    FROM target
    WHERE
        g.credential_id = target.credential_id
        AND g.updated_at = $3
    RETURNING
        target.credential_id,
        target.organization_id,
        g.updated_at AS grant_updated_at
),
revoked AS (
    UPDATE credentials c
    SET
        status = 'revoked',
        revoked_at = $7,
        failure_code = $8,
        failure_message = $9,
        updated_at = NOW()
    FROM tombstoned
    WHERE
        c.id = tombstoned.credential_id
        AND c.organization_id = tombstoned.organization_id
    RETURNING c.id, c.organization_id, c.slug, c.kind, c.credential_type, c.status, c.encrypted_payload, c.rotated_at, c.revoked_at, c.failure_code, c.failure_message, c.created_at, c.updated_at
),
deactivated AS (
    UPDATE data_sources ds
    SET
        is_active = false,
        test_error = COALESCE($9, 'Provider grant revoked'),
        last_tested_at = NOW(),
        connection_test_revision = ds.connection_test_revision + 1,
        updated_at = NOW()
    FROM revoked
    WHERE
        ds.credential_id = revoked.id
        AND ds.organization_id = revoked.organization_id
    RETURNING ds.credential_id
)
SELECT revoked.id, revoked.organization_id, revoked.slug, revoked.kind, revoked.credential_type, revoked.status, revoked.encrypted_payload, revoked.rotated_at, revoked.revoked_at, revoked.failure_code, revoked.failure_message, revoked.created_at, revoked.updated_at, tombstoned.grant_updated_at
FROM revoked
JOIN tombstoned ON tombstoned.credential_id = revoked.id
`

