const prunePipelineCompletionDetails = `-- name: PrunePipelineCompletionDetails :one
WITH pruned AS (
    DELETE FROM pipeline_completion_snapshots snapshot
    USING organizations o
    WHERE snapshot.organization_id = o.id AND o.slug = $1
        AND snapshot.completed_at < $2 AND snapshot.state IN ('refused', 'completed')
        AND snapshot.trigger_configuration IS NOT NULL
    RETURNING snapshot.id
), pruned_revisions AS (
    UPDATE pipeline_completion_trigger_revisions revision
    SET configuration = NULL
    FROM organizations o
    WHERE revision.organization_id = o.id AND o.slug = $1
        AND revision.revoked_at < $2 AND revision.configuration IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM pipeline_completion_snapshots snapshot
            WHERE snapshot.organization_id = revision.organization_id
                AND snapshot.project_environment_id = revision.project_environment_id
                AND snapshot.trigger_id = revision.trigger_id AND snapshot.trigger_revision = revision.revision
                AND snapshot.completed_at IS NULL)
    RETURNING revision.trigger_id
)
SELECT (SELECT count(*) FROM pruned) + (SELECT count(*) FROM pruned_revisions) AS pruned_count
`

type PrunePipelineCompletionDetailsParams struct {
	OrgSlug slug.Slug
	Cutoff  pgtype.Timestamptz
}

func (q *Queries) PrunePipelineCompletionDetails(ctx context.Context, arg PrunePipelineCompletionDetailsParams) (int64, error) {
	row := q.db.QueryRow(ctx, prunePipelineCompletionDetails, arg.OrgSlug, arg.Cutoff)
	var pruned_count int64
	err := row.Scan(&pruned_count)
	return pruned_count, err
}

const purgeProofObservationSnapshots = `-- name: PurgeProofObservationSnapshots :many
WITH selected AS (
    SELECT id FROM proof_observation_jobs
    WHERE organization_id = $1::integer AND project_environment_id = $2::bigint
        AND evidence_retain_until <= clock_timestamp() AND (target_ciphertext IS NOT NULL OR snapshot_ciphertext IS NOT NULL)
    ORDER BY id LIMIT 100 FOR UPDATE
)
UPDATE proof_observation_jobs job SET target_ciphertext = NULL, snapshot_ciphertext = NULL
FROM selected WHERE job.id = selected.id
RETURNING job.slug, job.request_digest
`

type PurgeProofObservationSnapshotsParams struct {
	OrganizationID       int32
	ProjectEnvironmentID int64
}

type PurgeProofObservationSnapshotsRow struct {
	Slug          slug.Slug
	RequestDigest string
}

func (q *Queries) PurgeProofObservationSnapshots(ctx context.Context, arg PurgeProofObservationSnapshotsParams) ([]PurgeProofObservationSnapshotsRow, error) {
	rows, err := q.db.Query(ctx, purgeProofObservationSnapshots, arg.OrganizationID, arg.ProjectEnvironmentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PurgeProofObservationSnapshotsRow
	for rows.Next() {
		var i PurgeProofObservationSnapshotsRow
		if err := rows.Scan(&i.Slug, &i.RequestDigest); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

