const recordPipelineWebhookDuplicate = `-- name: RecordPipelineWebhookDuplicate :one
WITH existing AS (
    SELECT id, payload_digest, run_slug, status
    FROM pipeline_webhook_deliveries
    WHERE receiver_id = $1
        AND delivery_id = $2
    FOR UPDATE
), updated AS (
    UPDATE pipeline_webhook_deliveries pwd
    SET duplicate_count = pwd.duplicate_count + 1,
        last_duplicate_at = $3,
        updated_at = $3
    FROM existing
    WHERE pwd.id = existing.id
        AND existing.payload_digest = $4
    RETURNING pwd.id
)
SELECT
    existing.payload_digest,
    existing.run_slug,
    existing.status,
    updated.id IS NOT NULL AS duplicate
FROM existing
LEFT JOIN updated ON updated.id = existing.id
`

type RecordPipelineWebhookDuplicateParams struct {
	ReceiverID    pgtype.Text
	DeliveryID    pgtype.Text
	ReceivedAt    pgtype.Timestamptz
	PayloadDigest pgtype.Text
}

type RecordPipelineWebhookDuplicateRow struct {
	PayloadDigest string
	RunSlug       string
	Status        string
	Duplicate     pgtype.Bool
}

// A signed duplicate is trusted only after receiver resolution and HMAC verification.
// The CTE locks an existing identity so concurrent callers cannot both report it as new.
func (q *Queries) RecordPipelineWebhookDuplicate(ctx context.Context, arg RecordPipelineWebhookDuplicateParams) (RecordPipelineWebhookDuplicateRow, error) {
	row := q.db.QueryRow(ctx, recordPipelineWebhookDuplicate,
		arg.ReceiverID,
		arg.DeliveryID,
		arg.ReceivedAt,
		arg.PayloadDigest,
	)
	var i RecordPipelineWebhookDuplicateRow
	err := row.Scan(
		&i.PayloadDigest,
		&i.RunSlug,
		&i.Status,
		&i.Duplicate,
	)
	return i, err
}

