const refreshOrganizationMemberInvitationToken = `-- name: RefreshOrganizationMemberInvitationToken :one
WITH refreshed AS (
    UPDATE organization_member_invitations omi
    SET
        token_hash = $1,
        expires_at = $2,
        last_sent_at = $3,
        updated_at = $3
    WHERE
        omi.organization_id = (
            SELECT id
            FROM organizations
            WHERE
                slug = $4
        )
        AND omi.slug = $5
        AND omi.status = 'pending'
    RETURNING
        id, organization_id, slug, email, role_id, invited_by_user_id, accepted_by_user_id, accepted_member_id, token_hash, status, expires_at, last_sent_at, accepted_at, declined_at, revoked_at, expired_at, created_at, updated_at
)
SELECT
    refreshed.id, refreshed.organization_id, refreshed.slug, refreshed.email, refreshed.role_id, refreshed.invited_by_user_id, refreshed.accepted_by_user_id, refreshed.accepted_member_id, refreshed.token_hash, refreshed.status, refreshed.expires_at, refreshed.last_sent_at, refreshed.accepted_at, refreshed.declined_at, refreshed.revoked_at, refreshed.expired_at, refreshed.created_at, refreshed.updated_at,
    o.slug AS organization_slug,
    r.slug AS role_slug,
    COALESCE(invited_by.slug::text, '') AS invited_by_user_slug,
    COALESCE(accepted_by.slug::text, '') AS accepted_user_slug
FROM
    refreshed
    JOIN organizations o ON refreshed.organization_id = o.id
    JOIN roles r ON refreshed.role_id = r.id
    LEFT JOIN users invited_by ON refreshed.invited_by_user_id = invited_by.id
    LEFT JOIN users accepted_by ON refreshed.accepted_by_user_id = accepted_by.id
`

