const refreshPipelineDraftProposal = `-- name: RefreshPipelineDraftProposal :one
WITH target AS (
    SELECT pd.id, pd.proposal_id, pd.refresh_attempt_id
    FROM pipeline_drafts pd
    JOIN projects p ON pd.project_id = p.id
    JOIN organizations o ON p.organization_id = o.id
    WHERE o.slug = $1
        AND p.slug = $2
        AND pd.pipeline_slug = $3
        AND pd.member_id = (
            SELECT om.id
            FROM organization_members om
            JOIN users u ON om.user_id = u.id
            WHERE om.organization_id = p.organization_id
                AND u.slug = $4
        )
), updated AS (
UPDATE pipeline_drafts pd
SET
    draft_state = $5,
    failed_at = NULL,
    failure_code = NULL,
    failure_message = NULL,
    branch_name = $6,
    branch_head_sha = $7,
    proposal_provider = $8,
    proposal_url = $9,
    proposal_state = $10,
    proposal_updated_at = NOW(),
    updated_at = NOW()
FROM target
WHERE pd.id = target.id
    AND target.proposal_id = $11
    AND target.refresh_attempt_id = $12
RETURNING pd.id
)
SELECT EXISTS(SELECT 1 FROM target) AS draft_exists,
       EXISTS(SELECT 1 FROM updated) AS updated
`

