const resolveNotificationRecord = `-- name: ResolveNotificationRecord :one
WITH target_record AS (
    SELECT nr.id
    FROM notification_records nr
    JOIN organizations o ON o.id = nr.organization_id
    WHERE o.slug = $1
        AND nr.slug = $2
),
updated AS (
    UPDATE notification_records nr
    SET lifecycle_state = 'resolved',
        resolved_at = CASE
            WHEN nr.lifecycle_state <> 'resolved' THEN COALESCE(nr.resolved_at, $3)
            ELSE nr.resolved_at
        END,
        updated_at = CASE
            WHEN nr.lifecycle_state <> 'resolved' OR nr.resolved_at IS NULL THEN CURRENT_TIMESTAMP
            ELSE nr.updated_at
        END
    FROM target_record
    WHERE nr.id = target_record.id
    RETURNING nr.id, nr.organization_id, nr.slug, nr.project_id, nr.environment_id, nr.notification_type, nr.severity, nr.lifecycle_state, nr.dedupe_fingerprint, nr.source_event_slug, nr.source_entity_type, nr.source_action, nr.source_refs, nr.safe_metadata, nr.first_seen_at, nr.last_seen_at, nr.occurrence_count, nr.last_occurrence_at, nr.dispatch_summary, nr.acknowledged_at, nr.resolved_at, nr.created_at, nr.updated_at
)
SELECT
    updated.id, updated.organization_id, updated.slug, updated.project_id, updated.environment_id, updated.notification_type, updated.severity, updated.lifecycle_state, updated.dedupe_fingerprint, updated.source_event_slug, updated.source_entity_type, updated.source_action, updated.source_refs, updated.safe_metadata, updated.first_seen_at, updated.last_seen_at, updated.occurrence_count, updated.last_occurrence_at, updated.dispatch_summary, updated.acknowledged_at, updated.resolved_at, updated.created_at, updated.updated_at,
    COALESCE((SELECT p.slug FROM projects p WHERE p.id = updated.project_id), '')::text AS project_slug,
    COALESCE((SELECT e.slug FROM environments e WHERE e.id = updated.environment_id), '')::text AS environment_slug
FROM updated
`

