// Pre-tenant webhook intake derives tenancy from the verified provider
// installation. The provider connection, repository, and target ref identify
// candidates; organization/project/environment/data-source/credential joins
// enforce the tenant boundary and fail closed for inactive credentials.
func (q *Queries) ResolveProofChangeWebhookMappings(ctx context.Context, arg ResolveProofChangeWebhookMappingsParams) ([]ResolveProofChangeWebhookMappingsRow, error) {
	rows, err := q.db.Query(ctx, resolveProofChangeWebhookMappings,
		arg.Provider,
		arg.ProviderConnectionID,
		arg.RepositoryID,
		arg.TargetRef,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ResolveProofChangeWebhookMappingsRow
	for rows.Next() {
		var i ResolveProofChangeWebhookMappingsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationSlug,
			&i.ProjectSlug,
			&i.EnvironmentSlug,
			&i.ProviderConnectionSlug,
			&i.Provider,
			&i.ProviderConnectionID,
			&i.RepositoryID,
			&i.TargetRef,
			&i.PipelinePath,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

