const saveCheckpoint = `-- name: SaveCheckpoint :one
WITH project_environment_row AS (
    SELECT pe.id AS project_environment_id
    FROM project_environments pe
    JOIN projects p ON pe.project_id = p.id
    JOIN organizations o ON p.organization_id = o.id
    JOIN environments e ON pe.environment_id = e.id
    WHERE o.slug = $10
        AND p.slug = $11
        AND e.slug = $12
        AND e.deleted_at IS NULL
        AND pe.deleted_at IS NULL
),
run_row AS (
    SELECT pr.project_environment_id
    FROM pipeline_runs pr
    JOIN project_environment_row pe ON pr.project_environment_id = pe.project_environment_id
    WHERE pr.run_slug = $1
)
INSERT INTO pipeline_checkpoint (
    project_environment_id,
    run_slug,
    step_slug,
    pipeline_spec,
    step_results,
    incremental_source_windows,
    compiled_plan,
    compiled_plan_digest,
    deployment_plan,
    deployment_resolution_digest
)
SELECT
    (SELECT project_environment_id FROM run_row),
    $1,
    $2,
    $3::jsonb,
    $4::jsonb,
    $5::jsonb,
    $6,
    $7,
    $8,
    $9
WHERE EXISTS (SELECT 1 FROM run_row)
ON CONFLICT (project_environment_id, run_slug) DO UPDATE
    SET step_slug = $2,
        pipeline_spec = $3::jsonb,
        step_results = $4::jsonb,
        incremental_source_windows = $5::jsonb,
        compiled_plan = $6,
        compiled_plan_digest = $7,
        deployment_plan = $8,
        deployment_resolution_digest = $9,
        updated_at = CURRENT_TIMESTAMP
RETURNING id, project_environment_id, run_slug, step_slug, pipeline_spec, step_results, incremental_source_windows, created_at, updated_at, compiled_plan, compiled_plan_digest, deployment_plan, deployment_resolution_digest
`

type SaveCheckpointParams struct {
	RunSlug                    string
	StepSlug                   string
	PipelineSpec               []byte
	StepResults                []byte
	IncrementalSourceWindows   []byte
	CompiledPlan               []byte
	CompiledPlanDigest         pgtype.Text
	DeploymentPlan             []byte
	DeploymentResolutionDigest pgtype.Text
	OrgSlug                    slug.Slug
	ProjectSlug                slug.Slug
	EnvironmentSlug            slug.Slug
}

// Checkpoint writes are active runtime operations, so they require an active
// environment catalog row and active project-environment enablement.
func (q *Queries) SaveCheckpoint(ctx context.Context, arg SaveCheckpointParams) (PipelineCheckpoint, error) {
	row := q.db.QueryRow(ctx, saveCheckpoint,
		arg.RunSlug,
		arg.StepSlug,
		arg.PipelineSpec,
		arg.StepResults,
		arg.IncrementalSourceWindows,
		arg.CompiledPlan,
		arg.CompiledPlanDigest,
		arg.DeploymentPlan,
		arg.DeploymentResolutionDigest,
		arg.OrgSlug,
		arg.ProjectSlug,
		arg.EnvironmentSlug,
	)
	var i PipelineCheckpoint
	err := row.Scan(
		&i.ID,
		&i.ProjectEnvironmentID,
		&i.RunSlug,
		&i.StepSlug,
		&i.PipelineSpec,
		&i.StepResults,
		&i.IncrementalSourceWindows,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CompiledPlan,
		&i.CompiledPlanDigest,
		&i.DeploymentPlan,
		&i.DeploymentResolutionDigest,
	)
	return i, err
}

