const updateAlertPolicy = `-- name: UpdateAlertPolicy :one
WITH org_row AS (
    SELECT id
    FROM organizations
    WHERE slug = $1
),
project_row AS (
    SELECT p.id, p.slug
    FROM projects p
    JOIN org_row o ON o.id = p.organization_id
    WHERE p.slug = $2
),
environment_row AS (
    SELECT e.id, e.slug
    FROM environments e
    JOIN org_row o ON o.id = e.organization_id
    WHERE e.slug = $3
        AND e.deleted_at IS NULL
),
project_environment_row AS (
    SELECT pe.project_id, pe.environment_id
    FROM project_environments pe
    JOIN project_row p ON p.id = pe.project_id
    JOIN environment_row e ON e.id = pe.environment_id
    WHERE pe.deleted_at IS NULL
),
updated AS (
    UPDATE alert_policies ap
    SET
        name = $4,
        scope = $5,
        project_id = (SELECT id FROM project_row),
        environment_id = (SELECT id FROM environment_row),
        notification_type = $6,
        severity = $7,
        lifecycle_state = $8,
        source_kind = $9,
        source_action = $10,
        source_ref = $11,
        enabled = $12,
        updated_at = NOW()
    FROM org_row
    WHERE ap.organization_id = org_row.id
        AND ap.slug = $13
        AND (
            $2::text IS NULL
            OR EXISTS (SELECT 1 FROM project_row)
        )
        AND (
            $3::text IS NULL
            OR EXISTS (SELECT 1 FROM environment_row)
        )
        AND (
            $3::text IS NULL
            OR EXISTS (SELECT 1 FROM project_environment_row)
        )
    RETURNING ap.id, ap.organization_id, ap.slug, ap.name, ap.scope, ap.project_id, ap.environment_id, ap.notification_type, ap.severity, ap.lifecycle_state, ap.source_kind, ap.source_ref, ap.enabled, ap.created_at, ap.updated_at, ap.source_action
)
SELECT
    updated.id, updated.organization_id, updated.slug, updated.name, updated.scope, updated.project_id, updated.environment_id, updated.notification_type, updated.severity, updated.lifecycle_state, updated.source_kind, updated.source_ref, updated.enabled, updated.created_at, updated.updated_at, updated.source_action,
    COALESCE((SELECT slug FROM project_row), '')::text AS project_slug,
    COALESCE((SELECT slug FROM environment_row), '')::text AS environment_slug,
    COALESCE(
        (
            SELECT ARRAY_AGG(ad.slug ORDER BY ad.slug)
            FROM alert_policy_destinations apd
            JOIN alert_destinations ad ON ad.id = apd.destination_id
            WHERE apd.alert_policy_id = updated.id
        ),
        ARRAY[]::text[]
    )::text[] AS destination_slugs
FROM updated
`

