const updateDataSourceCredentials = `-- name: UpdateDataSourceCredentials :exec
WITH target AS (
    SELECT
        ds.id,
        ds.credential_id AS old_credential_id
    FROM data_sources ds
    JOIN organizations o ON ds.organization_id = o.id
    WHERE
        o.slug = $1
        AND ds.slug = $2
        AND ds.deleted_at IS NULL
    FOR UPDATE OF ds
),
replacement AS (
    SELECT c.id
    FROM credentials c
    JOIN organizations o ON c.organization_id = o.id
    WHERE
        o.slug = $1
        AND c.slug = $3
),
attached AS (
    UPDATE data_sources ds
    SET
        credential_id = replacement.id,
        connection_test_revision = ds.connection_test_revision + 1,
        updated_at = NOW()
    FROM target, replacement
    WHERE ds.id = target.id
    RETURNING
        ds.id,
        target.old_credential_id,
        replacement.id AS new_credential_id
),
retired AS (
    UPDATE credentials c
    SET
        status = 'rotated',
        rotated_at = NOW(),
        encrypted_payload = NULL,
        updated_at = NOW()
    FROM attached
    WHERE
        c.id = attached.old_credential_id
        AND c.id <> attached.new_credential_id
        AND NOT EXISTS (
            SELECT 1
            FROM data_sources ds2
            WHERE
                ds2.credential_id = attached.old_credential_id
                AND ds2.id <> attached.id
        )
    RETURNING c.id
),
tombstoned_old_grants AS (
    UPDATE credential_oauth_grants g
    SET
        encrypted_token_set = decode('', 'hex'),
        updated_at = NOW()
    FROM retired
    WHERE g.credential_id = retired.id
    RETURNING g.credential_id
)
SELECT retired.id
FROM retired
LEFT JOIN tombstoned_old_grants ON tombstoned_old_grants.credential_id = retired.id
`

type UpdateDataSourceCredentialsParams struct {
	OrgSlug        slug.Slug
	DsSlug         slug.Slug
	CredentialSlug slug.Slug
}

func (q *Queries) UpdateDataSourceCredentials(ctx context.Context, arg UpdateDataSourceCredentialsParams) error {
	_, err := q.db.Exec(ctx, updateDataSourceCredentials, arg.OrgSlug, arg.DsSlug, arg.CredentialSlug)
	return err
}

