const updatePipelineTrigger = `-- name: UpdatePipelineTrigger :one
WITH target AS (
    SELECT
        pt.id AS trigger_id,
        ps.id AS pipeline_id,
        ps.slug AS pipeline_slug,
        pinned.id AS pinned_pipeline_version_id
    FROM pipeline_triggers pt
    JOIN project_environments pe ON pe.id = pt.project_environment_id
    JOIN projects p ON p.id = pe.project_id
    JOIN organizations o ON o.id = p.organization_id
    JOIN environments e ON e.id = pe.environment_id
        AND e.organization_id = o.id
    JOIN pipeline_specs current_ps ON current_ps.id = pt.pipeline_id
        AND current_ps.project_id = p.id
        AND current_ps.deleted_at IS NULL
    JOIN pipeline_specs ps ON ps.project_id = p.id
        AND ps.slug = $1
        AND ps.deleted_at IS NULL
    LEFT JOIN pipeline_versions pinned ON pinned.project_id = p.id
        AND pinned.pipeline_slug = ps.slug
        AND pinned.spec_hash = $2::text
    WHERE o.slug = $3
        AND p.slug = $4
        AND e.slug = $5
        AND e.deleted_at IS NULL
        AND pe.deleted_at IS NULL
        AND pt.slug = $6
        AND (
            $7 <> 'pinned'
            OR pinned.id IS NOT NULL
        )
),
updated AS (
    UPDATE pipeline_triggers pt
    SET
        pipeline_id = target.pipeline_id,
        pipeline_slug = target.pipeline_slug,
        pinned_pipeline_version_id = CASE
            WHEN $7 = 'pinned' THEN target.pinned_pipeline_version_id
            ELSE NULL
        END,
        completion_config = $8::jsonb,
        name = $9,
        trigger_type = $10,
        enabled = $11,
        revision = pt.revision + 1,
        version_policy = $7,
        runtime_input_keys = $12::text[],
        retry_enabled = $13,
        retry_max_attempts = $14,
        retry_backoff_strategy = $15,
        retry_initial_delay_seconds = $16,
        retry_max_delay_seconds = $17,
        retry_jitter = $18,
        retryable_failure_kinds = $19::text[],
        retry_max_elapsed_seconds = $20::integer,
        schedule_cron = CASE
            WHEN $10 = 'schedule' THEN $21::text
            ELSE NULL
        END,
        schedule_timezone = CASE
            WHEN $10 = 'schedule' THEN $22::text
            ELSE NULL
        END,
        schedule_misfire_policy = CASE
            WHEN $10 = 'schedule' THEN $23::text
            ELSE NULL
        END,
        receiver_id = CASE
            WHEN $10 = 'webhook' THEN $24::text
            ELSE NULL
        END,
        webhook_verification_strategy = CASE
            WHEN $10 = 'webhook' THEN $25::text
            ELSE NULL
        END,
        webhook_input_mappings = CASE
            WHEN $10 = 'webhook' THEN $26::jsonb
            ELSE NULL
        END,
        updated_by_actor_type = $27,
        updated_by_actor_slug = $28::text,
        disabled_at = CASE
            WHEN pt.enabled AND NOT $11 THEN NOW()
            WHEN $11 THEN NULL
            ELSE pt.disabled_at
        END,
        updated_at = NOW()
    FROM target
    WHERE pt.id = target.trigger_id
    RETURNING pt.id, pt.project_id, pt.project_environment_id, pt.pipeline_id, pt.pipeline_slug, pt.pinned_pipeline_version_id, pt.slug, pt.name, pt.trigger_type, pt.enabled, pt.revision, pt.version_policy, pt.runtime_input_keys, pt.retry_enabled, pt.retry_max_attempts, pt.retry_backoff_strategy, pt.retry_initial_delay_seconds, pt.retry_max_delay_seconds, pt.retry_jitter, pt.retryable_failure_kinds, pt.retry_max_elapsed_seconds, pt.schedule_cron, pt.schedule_timezone, pt.schedule_misfire_policy, pt.created_by_actor_type, pt.created_by_actor_slug, pt.updated_by_actor_type, pt.updated_by_actor_slug, pt.disabled_at, pt.created_at, pt.updated_at, pt.receiver_id, pt.webhook_verification_strategy, pt.webhook_input_mappings, pt.completion_config
)
SELECT
    updated.id, updated.project_id, updated.project_environment_id, updated.pipeline_id, updated.pipeline_slug, updated.pinned_pipeline_version_id, updated.slug, updated.name, updated.trigger_type, updated.enabled, updated.revision, updated.version_policy, updated.runtime_input_keys, updated.retry_enabled, updated.retry_max_attempts, updated.retry_backoff_strategy, updated.retry_initial_delay_seconds, updated.retry_max_delay_seconds, updated.retry_jitter, updated.retryable_failure_kinds, updated.retry_max_elapsed_seconds, updated.schedule_cron, updated.schedule_timezone, updated.schedule_misfire_policy, updated.created_by_actor_type, updated.created_by_actor_slug, updated.updated_by_actor_type, updated.updated_by_actor_slug, updated.disabled_at, updated.created_at, updated.updated_at, updated.receiver_id, updated.webhook_verification_strategy, updated.webhook_input_mappings, updated.completion_config,
    e.slug AS environment_slug,
    ps.slug AS pipeline_slug,
    pinned.spec_hash AS pinned_version_hash,
    ARRAY(SELECT pws.key_version FROM pipeline_webhook_secret_versions pws WHERE pws.pipeline_trigger_id = updated.id AND pws.enabled ORDER BY pws.key_version) AS enabled_key_versions
FROM updated
JOIN project_environments pe ON pe.id = updated.project_environment_id
JOIN environments e ON e.id = pe.environment_id
JOIN pipeline_specs ps ON ps.id = updated.pipeline_id
LEFT JOIN pipeline_versions pinned ON pinned.id = updated.pinned_pipeline_version_id
`

