const upsertOAuthGrant = `-- name: UpsertOAuthGrant :one
WITH credential AS (
    SELECT
        c.id,
        c.organization_id
    FROM credentials c
    JOIN organizations o ON o.id = c.organization_id
    WHERE
        o.slug = $1
        AND c.slug = $2
        AND c.kind = 'oauth2_grant'
        AND (
            ($3::text = 'organization_gitlab' AND EXISTS (
                SELECT 1 FROM organization_gitlab_connections connection
                WHERE connection.organization_id = c.organization_id AND connection.credential_id = c.id
            )) OR ($3::text = 'notification_connection' AND EXISTS (
                SELECT 1 FROM notification_connections connection
                WHERE connection.organization_id = c.organization_id AND connection.credential_id = c.id
                    AND connection.slug = $4
            )) OR ($3::text = 'data_source' AND EXISTS (
                SELECT 1 FROM data_sources ds
                WHERE ds.organization_id = c.organization_id AND ds.credential_id = c.id
                    AND ds.slug = $5 AND ds.deleted_at IS NULL
                    AND ds.organization_gitlab_connection_id IS NULL
            ))
        )
    FOR UPDATE OF c
),
upserted AS (
INSERT INTO
    credential_oauth_grants (
        credential_id,
        provider,
        encrypted_token_set,
        access_token_expires_at,
        scopes,
        account,
        last_refreshed_at
)
SELECT
    credential.id,
    $6,
    $7,
    $8,
    $9::text[],
    $10::jsonb,
    $11
FROM credential
ON CONFLICT (credential_id)
DO UPDATE SET
    provider = EXCLUDED.provider,
    encrypted_token_set = EXCLUDED.encrypted_token_set,
    access_token_expires_at = EXCLUDED.access_token_expires_at,
    scopes = EXCLUDED.scopes,
    account = EXCLUDED.account,
    last_refreshed_at = EXCLUDED.last_refreshed_at,
    updated_at = NOW()
WHERE credential_oauth_grants.updated_at = $12
RETURNING id, credential_id, provider, encrypted_token_set, access_token_expires_at, scopes, account, last_refreshed_at, created_at, updated_at
),
credential_updated AS (
    UPDATE credentials c
    SET updated_at = NOW()
    FROM upserted
    WHERE c.id = upserted.credential_id
    RETURNING c.id, c.organization_id, c.slug, c.kind, c.credential_type, c.status, c.encrypted_payload, c.rotated_at, c.revoked_at, c.failure_code, c.failure_message, c.created_at, c.updated_at
),
revision_bumped AS (
    UPDATE data_sources ds
    SET
        connection_test_revision = ds.connection_test_revision + 1,
        updated_at = NOW()
    FROM credential, upserted
    WHERE ds.credential_id = credential.id AND ds.organization_id = credential.organization_id
    RETURNING ds.id
)
SELECT
    c.id, c.organization_id, c.slug, c.kind, c.credential_type, c.status, c.encrypted_payload, c.rotated_at, c.revoked_at, c.failure_code, c.failure_message, c.created_at, c.updated_at,
    upserted.id AS grant_id,
    upserted.provider,
    upserted.encrypted_token_set,
    upserted.access_token_expires_at,
    upserted.scopes,
    upserted.account,
    upserted.last_refreshed_at,
    upserted.created_at AS grant_created_at,
    upserted.updated_at AS grant_updated_at
FROM upserted
JOIN credential_updated c ON c.id = upserted.credential_id
`

