const upsertPipelineDraft = `-- name: UpsertPipelineDraft :one
WITH project_row AS (
    SELECT p.id AS project_id, p.organization_id
    FROM projects p
    JOIN organizations o ON p.organization_id = o.id
    WHERE o.slug = $6
        AND p.slug = $7
),
version_row AS (
    SELECT pv.id
    FROM pipeline_versions pv
    JOIN project_row p ON pv.project_id = p.project_id
    WHERE pv.id = $3
        AND pv.pipeline_slug = $1
)
INSERT INTO pipeline_drafts (
    organization_id,
    project_id,
    pipeline_slug,
    member_id,
    based_on_version_id,
    spec_jsonb,
    draft_state,
    updated_at
)
SELECT
    p.organization_id,
    p.project_id,
    $1,
    (
        SELECT om.id
        FROM organization_members om
        JOIN users u ON om.user_id = u.id
        WHERE om.organization_id = p.organization_id
            AND u.slug = $2
    ),
    CASE
        WHEN $3::bigint IS NULL THEN NULL
        ELSE (SELECT id FROM version_row)
    END,
    $4,
    $5,
    NOW()
FROM project_row p
JOIN pipeline_specs ps ON ps.project_id = p.project_id
    AND ps.slug = $1
    AND ps.deleted_at IS NULL
WHERE $3::bigint IS NULL
    OR EXISTS (SELECT 1 FROM version_row)
ON CONFLICT (project_id, pipeline_slug, member_id)
DO UPDATE SET
    based_on_version_id = EXCLUDED.based_on_version_id,
    spec_jsonb = EXCLUDED.spec_jsonb,
    draft_state = EXCLUDED.draft_state,
    failed_at = NULL,
    failure_code = NULL,
    failure_message = NULL,
    updated_at = NOW()
RETURNING id, project_id, pipeline_slug, member_id, based_on_version_id, spec_jsonb, draft_state, base_ref, base_commit_sha, branch_name, branch_head_sha, proposal_provider, proposal_id, proposal_url, proposal_state, last_proposed_draft_hash, queued_at, proposal_updated_at, failed_at, created_at, updated_at, publish_attempt_id, refresh_attempt_id, failure_code, failure_message, proposal_authority_id, publication_mode, provider_host, provider_account_id, provider_repository_id, provider_credential_id, executing_principal_id, executing_principal_display, authority_source, organization_id
`

