const upsertRuntimeVariable = `-- name: UpsertRuntimeVariable :one
WITH target_environment AS (
    SELECT
        o.id AS organization_id,
        e.id AS environment_id,
        e.slug AS environment_slug
    FROM
        organizations o
        JOIN environments e ON e.organization_id = o.id
    WHERE
        o.slug = $1
        AND e.slug = $2
        AND e.deleted_at IS NULL
), upserted AS (
    INSERT INTO
        environment_runtime_variables (
            organization_id,
            environment_id,
            key,
            value_type,
            value_text,
            description
        )
    SELECT
        target_environment.organization_id,
        target_environment.environment_id,
        $3,
        $4,
        $5,
        $6
    FROM target_environment
    ON CONFLICT (environment_id, key)
        DO UPDATE SET
            value_type = EXCLUDED.value_type,
            value_text = EXCLUDED.value_text,
            description = EXCLUDED.description,
            updated_at = NOW()
    RETURNING
        id, organization_id, environment_id, key, value_type, value_text, description, created_at, updated_at
)
SELECT
    upserted.id, upserted.organization_id, upserted.environment_id, upserted.key, upserted.value_type, upserted.value_text, upserted.description, upserted.created_at, upserted.updated_at,
    target_environment.environment_slug
FROM
    upserted
    JOIN target_environment
        ON target_environment.environment_id = upserted.environment_id
`

